@import url('src/design/tokens.css'); /* the design system's tokens come first (BRIEF-DESIGN-SYSTEM); build.mjs puts the file in their place */
/* =====================================================================
   GHOSTY — one design (route C, the owner's pick) in the colour of a theme.
   A theme (state/theme.ts: Reactor, the default, and Graphite) sets only the accent and what is made from it,
   on <html>: --c the accent and --cr its "r,g,b"; --c2 a pale tint of it; --halo1 / --halo2 the glow behind
   Home's hero and --room / --room2 the room's light, at the theme's own strength. It never changes layout,
   type or spacing. The values below are Reactor's, for the first frame. Every theme shares --a (amber, only
   for warnings), --r (alerts) and the graphite canvas (--bg); --ar / --bgr are "r,g,b" triplets.
   ===================================================================== */
:root {
  --c: #64d2ff; --cr: 100,210,255; --c2: #bff0ff;
  --halo1: rgba(100,210,255,.17); --halo2: rgba(100,210,255,.06); --room: rgba(100,210,255,.09); --room2: rgba(100,210,255,.16);
  --a: #ffb340; --ar: 255,179,64; --r: #ff6961;
  --bg: #050607; --bgr: 5,6,7;
  /* viewer position (-1..1), written each frame by engine/space.ts: pointer or phone tilt */
  --px: 0; --py: 0;
  color-scheme: dark;
}
@media (prefers-reduced-motion: reduce) { :root { --dx: 0px; --dy: 0px; } }
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
[hidden] { display: none !important; }
html, body { height: 100%; margin: 0; overflow: hidden; color: var(--fg); overscroll-behavior: none; }
html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; } /* iPhone Safari would enlarge text on its own when the phone turns sideways */
body { position: fixed; inset: 0; }
#gl { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; background: var(--bg); }
body::after { content: ''; position: fixed; inset: 0; pointer-events: none; z-index: 3; }
#app { position: fixed; inset: 0; z-index: 5; display: flex; flex-direction: column; pointer-events: none; padding: env(safe-area-inset-top, 0) env(safe-area-inset-right, 0) env(safe-area-inset-bottom, 0) env(safe-area-inset-left, 0); }
#app button, #app input, #app textarea, #app select, #app a, #app .pn, #app .rw.link { pointer-events: auto; }
::selection { color: #fff; }
::-webkit-scrollbar-thumb { background: rgba(var(--cr), .18); border-radius: 3px; } ::-webkit-scrollbar-track { background: transparent; }

/* ---------- controls ---------- */
button {
  text-transform: uppercase; 
  cursor: pointer; white-space: nowrap;
}
/* hover only where there is a mouse: iPhone Safari keeps a tapped button in its hover look until the next tap elsewhere */
@media (hover: hover) { button.warn:hover { border-color: var(--a); } }
button:disabled { cursor: default; }
input, textarea, select {
  background: rgba(var(--cr), .04); 
  width: 100%; min-width: 0; 
}
textarea { resize: vertical; }
input:focus, textarea:focus, select:focus { outline: 0; border-color: rgba(var(--cr), .6); background: rgba(var(--cr), .07); }
input[type=checkbox] { width: auto; accent-color: var(--c); }
select { appearance: none; -webkit-appearance: none; }
.lnk { text-decoration: none; }
.lnk:hover { border-bottom-color: var(--c); }

/* ---------- top bar ---------- */
#top { position: relative; flex: none; display: flex; pointer-events: auto; }
/* the signal line: still when idle, flowing while Ghosty thinks, bright while he speaks */
#top::after { content: ''; position: absolute; }
@keyframes signal { from { background-position: 100% 0; } to { background-position: -100% 0; } }
#top .logo { align-items: center; cursor: pointer; border: 0; }
#top .logo:hover { color: var(--c); background: none; }
#top .logo .caret { width: 0; height: 0; margin-left: -6px; border: 3.5px solid transparent; border-top-color: rgba(var(--cr), .7); transform: translateY(2px); }
#top .logo .ic { fill: none; }
#top .tstatus { font: 400 10px var(--m); color: var(--c); letter-spacing: .04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 40vw; }
#top .sp { flex: 1; }
#top .cmd { border-color: rgba(var(--cr), .18); }
#top .cmd:hover { color: #fff; }
#top .clock { font: 400 11px var(--m); letter-spacing: .06em; color: rgba(var(--cr), .8); font-variant-numeric: tabular-nums; }
#top .conn { width: 6px; height: 6px; border-radius: 50%; }
#top .conn.on { background: var(--c); box-shadow: 0 0 8px rgba(var(--cr), .7); }
#top .conn.off { background: var(--r); }
@keyframes breath { 50% { opacity: .45; } }

/* ---------- stage + pages ---------- */
#stage { flex: 1; min-height: 0; position: relative; perspective: 1600px; perspective-origin: calc(50% + var(--px) * 5%) calc(45% + var(--py) * 5%); }
.pg { position: absolute; inset: 0; display: none; transform-style: preserve-3d; }
.pg.on { display: block; }
@keyframes pgin { from { opacity: 0; } }
.hud { position: absolute; inset: 0; display: grid; padding: 8px 12px 8px; pointer-events: none; transform-style: preserve-3d; }
/* The side columns float in the volume: a little tilt towards the viewer, a drift with --dx/--dy. */
.two > .cL, .hud.core > .cside.l { transform-origin: 100% 50%; transform: translate3d(var(--dx), var(--dy), 0) rotateY(var(--tilt)); backface-visibility: hidden; }
.two > .cR, .hud.core > .cside.r { transform-origin: 0 50%; transform: translate3d(var(--dx), var(--dy), 0) rotateY(calc(var(--tilt) * -1)); backface-visibility: hidden; }
.two > .hero, .hud.core > .ccenter { transform: translate3d(calc(var(--dx) * -.5), calc(var(--dy) * -.5), 0); }
@media (max-width: 899px) { .two > .hero, .hud.core > .ccenter { transform: none; } }
/* Assemble: panes settle into place, one after another, quickly. */
.pg.on .col > .pn:nth-child(2), .pg.on .cside > .pn:nth-child(2) { --i: 1; } .pg.on .col > .pn:nth-child(3), .pg.on .cside > .pn:nth-child(3) { --i: 2; } .pg.on .col > .pn:nth-child(4) { --i: 3; } .pg.on .col > .pn:nth-child(n+5) { --i: 4; }
@keyframes pnin { from { opacity: 0; transform: translateY(8px); } }
.hud > * { pointer-events: none; min-height: 0; min-width: 0; }
/* A column takes the touches between its panels too: a swipe there scrolls it instead of reaching the scene behind.
   Inner scrollers (.col, .pn > .bd) pass a swipe on when they have nothing to scroll: iPhone Safari honours
   overscroll-behavior: contain even then, which left whole pages unable to scroll. */
@media (max-width: 899px), (hover: none) { .hud .col { pointer-events: auto; } } /* (on a desktop the empty column space still reaches the scene) */

/* ---------- panels ---------- */
.pn {
  position: relative; display: flex; flex-direction: column; min-height: 0; overflow: hidden;
}
/* the one motif: a small corner tick, like a registration mark on a drawing */
.pn::before { content: ''; position: absolute; left: -1px; top: -1px; width: 9px; height: 9px; border-left: 1px solid rgba(var(--cr), .85); border-top: 1px solid rgba(var(--cr), .85); border-top-left-radius: var(--rad); pointer-events: none; z-index: 1; }
.pn > h3 { flex: none; margin: 0; display: flex; align-items: center; text-transform: uppercase; cursor: pointer; -webkit-user-select: none; user-select: none; }
.pn > h3 .sp { flex: 1; }
.pn > h3 small { overflow: hidden; text-overflow: ellipsis; text-transform: none; }
.pn > h3 .light { width: 5px; height: 5px; border-radius: 50%; background: var(--c); box-shadow: 0 0 6px rgba(var(--cr), .8); flex: none; }
.pn > h3 .light.mid { background: var(--a); box-shadow: 0 0 6px rgba(var(--ar), .7); }
.pn > h3 .light.off { background: var(--r); box-shadow: none; opacity: .9; }
.pn > .bd { flex: 1; min-height: 0; display: flex; flex-direction: column; overflow-x: hidden; overflow-y: auto; overscroll-behavior: auto; -webkit-overflow-scrolling: touch; scrollbar-width: thin; scrollbar-color: rgba(var(--cr), .25) transparent; }
.pn > .ft { flex: none; display: flex; align-items: center; gap: 8px; }
.pn.min { flex: none !important; }
.pn.min > .bd, .pn.min > .ft, .pn.min > .tabs, .pn.min > .keyrow { display: none; }
.pn.min > h3 { border-bottom: 0; }
.pn.fx { flex: none !important; }
.pn > .tabs, .pn > .keyrow { flex: none; }

/* rows */
.rw { flex: none; display: flex; align-items: center; min-width: 0; }
.rw .k { text-transform: uppercase; flex: none; }
.rw .v { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--fg); }
.rw.wrap .v { white-space: normal; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; }
.rw .n { flex: none; }
.rw .n.del { cursor: pointer; } .rw .n.del:hover { color: var(--r); }
.rw .sev { align-self: stretch; flex: none; }
.rw.link { cursor: pointer; } .rw.link:hover { background: rgba(var(--cr), .07); }
.rw .spark { width: 60px; height: 18px; flex: none; }
.big { color: #fff; }
.row { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: nowrap; }
.row.wrap { flex-wrap: wrap; }
.row .sp { flex: 1; }
.keyrow { display: flex; align-items: center; }
.keyblock { display: flex; flex-direction: column; flex: none; }
/* LINKS → TELEGRAM: the pairing code, big enough to copy into the Telegram app */
.tgcode { color: var(--c); text-align: center; padding: 10px 0 4px; }
.tabs { display: flex; }
.spark { width: 100%; height: 34px; display: block; }
.empty { flex: 1; color: var(--mute); }
@keyframes blink { 50% { opacity: .35; } }
.bar { display: flex; flex: none; }
.bar span { flex: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bar .gauge { flex: 1; position: relative; }
.bar .gauge i { position: absolute; left: 0; top: 0; bottom: 0; }

/* ---------- two-column page ---------- */
.two { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
.two > .hero { display: flex; flex-direction: column; position: relative; }
.two .tag { font: 400 10px var(--d); letter-spacing: .32em; color: rgba(var(--cr), .85); text-transform: uppercase; align-items: center; gap: 10px; }
.two .tag::before { content: ''; display: inline-block; width: 16px; height: 1px; background: rgba(var(--cr), .7); }
.two .bigv { position: relative; }
.two .swap { position: absolute; }
.col { display: flex; flex-direction: column; min-height: 0; overflow-y: auto; overscroll-behavior: auto; scrollbar-width: none; }
.col > .pn { min-height: 160px; }
.dials { display: none; gap: 20px; justify-content: center; position: absolute; left: 0; right: 0; bottom: 14px; }
.dial { display: flex; flex-direction: column; align-items: center; gap: 4px; width: 68px; }
.dial svg { width: 56px; height: 56px; }
.dial circle { fill: none; stroke-width: 2; stroke-linecap: round; } .dial .track { stroke: rgba(var(--cr), .12); }
.dial text { fill: #fff; } .dial span { font: 500 9px var(--d); letter-spacing: .18em; color: var(--mute); text-transform: uppercase; }
@media (max-width: 899px) {
  .two:not(.alt) > .cR { display: none; }
  .two.alt > .cL { display: none; }
}
@media (min-width: 900px) {
  .two { grid-template-columns: minmax(280px, 350px) minmax(0, 1fr) minmax(280px, 350px); grid-template-rows: minmax(0, 1fr); padding-right: 16px; gap: 14px; }
  .two > .cL { order: 1; } .two > .hero { order: 2; }
  .two > .cR { order: 3; } .two .swap { display: none; } 
}
@media (min-width: 900px) and (min-height: 560px) { .dials { display: flex; } }

/* ---------- dock ---------- */
#dock { flex: none; display: flex; justify-content: center; pointer-events: auto; -webkit-backdrop-filter: blur(16px); }
#dock button { display: flex; border: 0; }
#dock button .ic { stroke: currentColor; fill: none; stroke-linecap: round; stroke-linejoin: round; }
#dock button:hover { background: none; color: var(--fg); }
#dock button.on .ic { filter: drop-shadow(0 0 6px rgba(var(--cr), .6)); }
#dock button.on::before { content: ''; position: absolute; left: 50%; top: 0; width: 18px; height: 1px; margin-left: -9px; background: var(--c); box-shadow: 0 0 8px var(--c); }
@media (min-width: 900px) {
  #dock { -webkit-backdrop-filter: none; }
  #dock button span { left: 52px; top: 50%; white-space: nowrap; border: 1px solid var(--line); border-radius: var(--rad); pointer-events: none; }
  #dock button:hover span { opacity: 1; }
  #dock button.on::before { left: 0; top: 50%; width: 2px; height: 18px; margin: -9px 0 0; }
}

/* ---------- boot + pairing ---------- */
#boot { position: fixed; inset: 0; z-index: 200; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: opacity .6s; }
#boot.out { opacity: 0; pointer-events: none; }
#pair { position: fixed; inset: 0; z-index: 210; display: flex; align-items: center; justify-content: center; padding: 16px; background: rgba(var(--bgr), .9); }
#pair .bx { width: min(420px, 100%); display: flex; flex-direction: column; }
#pair h2 { margin: 0; }
#pair p { margin: 0; color: var(--fg); }
#pair .pairtip { margin-top: -6px; font-size: 12px; color: var(--mute); }
/* The sign-in form's username: there for iPhone's Passwords, never seen (display:none would hide it from password managers). */
#pairform .pairuser { position: absolute; width: 1px; height: 1px; min-height: 0; padding: 0; border: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); opacity: 0; pointer-events: none; }

/* ---------- toasts, modal, palette ---------- */
#toasts { position: fixed; left: 50%; transform: translateX(-50%); z-index: 150; display: flex; flex-direction: column; align-items: center; pointer-events: none; width: min(92vw, 440px); }
.toast { color: #fff; max-width: 100%; }
.toast.warn { border-left-color: var(--a); } .toast.bad { border-left-color: var(--r); } .toast.ok { border-left-color: var(--ok); }
.toast.out { opacity: 0; transition: opacity .4s; }
@keyframes tin { from { opacity: 0; transform: translateY(-6px); } }
.modal { position: fixed; inset: 0; z-index: 130; display: flex; align-items: center; justify-content: center; }
.mbox { width: min(900px, 100%); height: min(720px, 100%); display: flex; flex-direction: column; overflow: hidden; }
.mhead { display: flex; align-items: center; justify-content: space-between; }
.mbody { flex: 1; min-height: 0; display: flex; }
/* ---------- street view / satellite / live traffic: Google's and Waze's pages in a locked frame (ui/mapsheet.ts) ---------- */
.mapsheet { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 6px; padding: 8px 10px 10px; }
.mapbar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; justify-content: space-between; }
.maptabs { display: flex; gap: 4px; }
.maptabs button { padding: 6px 8px; min-height: 0; font-size: 8.5px; }
.mapwhere { font: 400 9px var(--m); letter-spacing: .14em; color: var(--mute); }
.mapframe { flex: 1 1 auto; min-height: 0; width: 100%; border: 0; background: #000; }
.mapnote { font: 400 11px/1.4 var(--b); color: var(--mute); }
/* the flat map (ui/flatmap.ts): Leaflet in Ghosty's colours */
.flathost { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: 5px; }
.fmbar { display: flex; flex-direction: column; gap: 4px; }
.fmsearchrow { display: flex; gap: 4px; }
.fmsearch { flex: 1 1 auto; min-width: 0; }
.fmchips { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; padding-bottom: 1px; }
.fmchips::-webkit-scrollbar { display: none; }
.fmchip { flex: none; padding: 6px 8px; min-height: 0; font-size: 8.5px; white-space: nowrap; }
.fmhint { opacity: .65; }
.flatmap { flex: 1 1 auto; min-height: 220px; position: relative; z-index: 0; background: #02070d; }
/* DARK: OpenStreetMap's tiles inverted and hue-rotated (water stays blue), dimmed to sit with the HUD */
.leaflet-layer.osm-dark { filter: invert(1) hue-rotate(180deg) brightness(.82) contrast(.92) saturate(.6); }
.fminfo { font: 400 10px/1.4 var(--m); color: var(--a); letter-spacing: .04em; }
.fmsteps { max-height: 26vh; overflow: auto; font: 400 11px/1.45 var(--b); color: var(--mute); border-top: 1px solid var(--line); padding-top: 4px; }
.fmsteps b { display: block; color: #fff; margin-bottom: 3px; }
.leaflet-container { font: 400 11px var(--b); background: #02070d; }
.leaflet-container .leaflet-control-attribution { font-size: 8px; background: rgba(2,7,13,.75); color: #9ab; max-width: 62%; text-align: right; }
.leaflet-container .leaflet-control-attribution a { color: #9ab; }
.leaflet-container .leaflet-control-scale-line { background: rgba(2,7,13,.6); color: #cfe9f7; border-color: rgba(var(--cr), .6); font: 400 9px var(--m); }
.fmpopup .leaflet-popup-content-wrapper { background: #02070d; color: #dfe9f2; border-radius: 0; box-shadow: inset 0 0 0 1px rgba(var(--cr), .5), 0 10px 30px rgba(0,0,0,.6); }
.fmpopup .leaflet-popup-tip { background: #02070d; }
.fmpopup .leaflet-popup-close-button { color: var(--c); }
.fmpop { font: 400 12px/1.4 var(--b); }
.fmpop > b { display: block; color: var(--a); font: 500 11px var(--m); letter-spacing: .1em; }
.fmaddr { color: var(--mute); margin: 4px 0; }
.fmpc { font: 500 9px var(--m); color: var(--c); letter-spacing: .14em; margin-top: 2px; }
.fmout { margin: 4px 0; }
.fmwiki { margin: 5px 0; }
.fmwiki b { display: block; color: #fff; font: 500 11px var(--b); }
.fmwiki span { display: block; color: var(--mute); }
.fmbtns { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.fmbtns button { padding: 6px 8px; min-height: 0; font-size: 8.5px; }
.fmlabel { background: rgba(2,7,13,.9); color: #fff; border: 1px solid rgba(var(--cr), .5); font: 500 9px var(--m); letter-spacing: .1em; border-radius: 0; box-shadow: none; padding: 2px 5px; }
.fmlabel::before { display: none; }
/* ---------- journeys: the GO panel and the JOURNEY sheet under the map (ui/journeysheet.ts) ---------- */
/* With a panel under it the map gives up some height and never paints over the panel (a phone has room for both). */
.mapsheet.withbelow .flathost { overflow: hidden; }
.mapsheet.withbelow .flatmap { min-height: 150px; }
.jsheet { flex: none; max-height: min(34vh, 300px); overflow: auto; overscroll-behavior: auto; display: flex; flex-direction: column; gap: 6px; border-top: 1px solid var(--line); padding-top: 6px; }
.jsheet[hidden] { display: none; }
.jhead { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; min-width: 0; }
.jhead b { font: 500 10px var(--d); letter-spacing: .16em; color: var(--c); text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.jwhen { font: 400 9px var(--m); letter-spacing: .1em; color: var(--mute); white-space: nowrap; }
.jtabs { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; flex: none; }
.jtabs::-webkit-scrollbar { display: none; }
.jtab { flex: none; display: flex; flex-direction: column; align-items: flex-start; gap: 1px; padding: 5px 9px; text-align: left; letter-spacing: 0; text-transform: none; }
.jtab b { font: 500 12px var(--d); color: var(--fg); }
.jtab small { font: 400 9px var(--m); color: var(--mute); }
.jtab.on small { color: var(--c); }
.jsteps { display: flex; flex-direction: column; }
.jstep { display: flex; align-items: center; gap: 8px; padding: 6px 2px; border-bottom: 1px solid var(--line2); cursor: pointer; min-width: 0; }
.jstep:last-child { border-bottom: 0; }
.jstep:hover, .jstep.on { background: rgba(var(--cr), .07); }
.jic { flex: none; width: 18px; height: 18px; display: flex; } .jic svg { width: 18px; height: 18px; fill: currentColor; }
.jbadge { flex: none; display: inline-block; min-width: 24px; padding: 2px 6px; font: 600 11px var(--m); font-style: normal; text-align: center; letter-spacing: .04em; }
.jtext { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; font: 400 11px/1.35 var(--b); color: var(--mute); }
.jtext b { font-weight: 500; color: var(--fg); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.jtext span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.jtext em { font: 400 9px var(--m); font-style: normal; letter-spacing: .1em; text-transform: uppercase; color: var(--ok); }
.jtext em.late { color: var(--a); } .jtext em.jcancel { color: var(--r); }
.jtime { flex: none; display: flex; flex-direction: column; align-items: flex-end; font: 400 11px var(--m); color: var(--fg); font-variant-numeric: tabular-nums; }
.jtime small { font-size: 9px; color: var(--mute); }
.jacts { display: flex; gap: 4px; flex-wrap: wrap; } .jacts button { padding: 6px 8px; font-size: 8.5px; }
.jcredit { font: 400 9px var(--m); color: var(--mute); letter-spacing: .04em; }
.jform { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 6px; padding: 10px 12px 12px; overflow: auto; }
.jform .lab { margin-top: 2px; }
.jin { width: 100%; box-sizing: border-box; }
.jchips { display: flex; gap: 4px; flex-wrap: wrap; } .jchips button { padding: 6px 9px; font-size: 8.5px; }
.jhint { font: 400 10.5px/1.4 var(--b); color: var(--mute); }
.jerr { font: 400 11.5px/1.4 var(--b); color: var(--a); border-left: 2px solid var(--a); padding-left: 8px; }
.jres { display: flex; flex-direction: column; }
.jopt { display: grid; grid-template-columns: auto 1fr; gap: 2px 10px; align-items: center; padding: 8px 2px; border-bottom: 1px solid var(--line2); cursor: pointer; min-width: 0; }
.jopt:hover { background: rgba(var(--cr), .07); }
.jopt b { font: 500 13px var(--m); color: var(--fg); font-variant-numeric: tabular-nums; white-space: nowrap; }
.jopt > span { font: 400 11px var(--b); color: var(--mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.jopt .jlines { grid-column: 1 / -1; display: flex; gap: 4px; flex-wrap: wrap; }
.jlines .jwalk { font: 400 10px var(--m); font-style: normal; color: var(--mute); letter-spacing: .08em; }
.jnone { font: 400 11.5px/1.4 var(--b); color: var(--mute); padding: 6px 0; }
iframe.sandbox { flex: 1; border: 0; width: 100%; background: #02070d; }
#palette { position: fixed; inset: 0; z-index: 140; display: none; justify-content: center; }
#palette.on { display: flex; }
#palette .bx { width: min(600px, 100%); display: flex; flex-direction: column; overflow: hidden; }
#palette input { min-height: 0; }
#palette .ls { overflow: auto; }
#palette .it { display: flex; align-items: center; cursor: pointer; }
#palette .it.sel, #palette .it:hover { border-left-color: var(--c); }
#palette .it small { min-width: 54px; text-transform: uppercase; }
#palette .it span { flex: 1; } #palette .it em { color: var(--mute); }
#palette .hint { display: flex; gap: 16px; padding: 7px 18px; }

/* ---------- CORE ---------- */
.hud.core { grid-template-columns: minmax(0, 1fr); }
.ccenter { display: flex; flex-direction: column; min-height: 0; }
.ccenter > * { pointer-events: auto; }
.rwrap { display: flex; align-items: center; justify-content: center; pointer-events: none !important; }
canvas.reactor { display: block; }
#cstate { text-align: center; }
#glance { gap: 18px; justify-content: center; flex-wrap: wrap; padding: 2px 8px; max-width: min(640px, 94vw); }
#glance .gi { display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 64px; }
#glance small { font: 500 8.5px var(--d); letter-spacing: .2em; color: var(--mute); text-transform: uppercase; }
#glance b { font: 400 10.5px var(--m); color: var(--c); letter-spacing: .02em; white-space: nowrap; max-width: 150px; overflow: hidden; text-overflow: ellipsis; }
#glance .gi.warn b { color: var(--a); } #glance .gi.bad b { color: var(--r); }
#glance b[data-case="keep"] { text-transform: uppercase; }
#glance:empty { display: none; }
#ccap { overflow-y: auto; pointer-events: auto; cursor: pointer; }
#ccap:empty, #ccap span:empty { display: none; }
#ccap.fade { opacity: 0; transform: translateY(-6px); }
#ccap span { display: block; }
#cbar #cin { border-color: transparent; }
#cbar #cin:focus { border-color: transparent; background: rgba(var(--cr), .04); }
#cbar button { font-size: 9.5px; } #cbar button:where(:not(#mic)) { padding: 8px 10px; }
#mic, #lensbtn { flex: none; display: grid; place-items: center; }
#mic .ic, #lensbtn .ic { stroke: #fff; fill: none; stroke-linecap: round; }
#mic.on { border-color: var(--ok); }
@keyframes micon { 50% { box-shadow: 0 0 0 9px rgba(79,227,168,.04); } }
#chips { display: flex; justify-content: center; flex-wrap: wrap; width: min(680px, 100%); }
#chips button { font-size: 9px; min-height: 0; }
.cside { display: none; flex-direction: column; gap: 8px; min-height: 0; }
.convo .log { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; scrollbar-width: thin; scrollbar-color: rgba(var(--cr), .25) transparent; }
.msg { white-space: pre-wrap; word-break: break-word; }
.msg.err { border-left-color: var(--r); }
.msg .offchip { display: inline-block; margin-top: 4px; border-radius: 9px; color: var(--c); white-space: nowrap; }
.msg small { display: block; }
/* ---- THINK HARDER: a button under the latest answer; the answer with how sure it is, its working folded away ---- */
.msg .thinkrow { flex-wrap: wrap; }
.msg .thinkrow button, .msg.think .row button { font-size: 9px; padding: 4px 9px; min-height: 0; }
.msg.think { border-left-color: var(--ok); }
.msg.think .thinkans { display: block; font-weight: 600; color: var(--fg); }
.msg.think .thinkline { display: flex; gap: 8px; align-items: center; font: 400 11px var(--m); color: var(--c); white-space: normal; }
.msg.think .thinkline i { width: 6px; height: 6px; border-radius: 50%; background: var(--ok); flex: none; animation: blink .8s infinite; }
.msg.think .thinkconf { font: 400 10.5px var(--m); color: var(--mute); margin-top: 2px; white-space: normal; }
.msg.think .thinkconf.checked { color: var(--ok); } .msg.think .thinkconf.agree { color: var(--c); }
.msg.think .thinkconf.failed-check, .msg.think .thinkconf.split, .msg.think .thinkconf.none { color: var(--a); }
.msg.think .thinkwork { margin-top: 4px; font-size: 12px; color: rgba(232,241,246,.8); }
.msg.think .thinkwork summary { cursor: pointer; font: 500 8.5px var(--d); letter-spacing: .16em; color: var(--mute); }
.msg.think .row { margin-top: 5px; display: flex; gap: 6px; flex-wrap: wrap; }
.act { display: flex; align-items: center; gap: 8px; }
.act i { flex: none; }
.act.running i { animation: blink .8s infinite; } .act.fail i { background: var(--r); }
.act em { font-style: normal; color: #ff9aa6; flex-basis: 100%; padding-left: 14px; white-space: pre-wrap; }
.act.fail { flex-wrap: wrap; }
/* ---- live progress: what a tool is doing right now, under its line (and on the HUD ring) ---- */
.act.live { flex-wrap: wrap; }
.act .prog { flex-basis: 100%; display: flex; flex-direction: column; gap: 3px; padding-left: 13px; color: rgba(var(--cr), .85); letter-spacing: .02em; }
.act .prog span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.act .prog .pbar { width: min(220px, 100%); background: rgba(var(--cr), .18); overflow: hidden; }
.act .prog .pbar b { display: block; height: 100%; background: var(--c); transition: width .3s ease; }
.hudtask { position: absolute; transform: translate(-50%, -50%); max-width: 72%; color: var(--c); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hudtask[hidden] { display: none; }
.msg a { text-decoration: underline; text-underline-offset: 2px; word-break: break-all; }
/* cited answers (features/core/cited.ts): [n] chips, the SOURCES list, the claim-check line */
.msg .cite { display: inline-grid; place-items: center; min-width: 24px; height: 22px; margin: 0 2px; padding: 0 6px; vertical-align: 1px; border-radius: 10px; color: var(--c); letter-spacing: 0; text-decoration: none; word-break: normal; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.msg .cite:active { transform: scale(.92); }
.msg .cite.miss { border-color: var(--r); color: #ffb3bd; background: rgba(255,77,94,.12); border-style: dashed; }
.msg mark.unconf { background: rgba(var(--ar), .14); color: inherit; text-decoration: underline wavy rgba(var(--ar), .8); text-underline-offset: 3px; border-radius: 2px; }
.msg .citesrc { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; padding-top: 6px; border-top: 1px solid rgba(var(--cr), .2); white-space: normal; }
.msg .csrc { display: grid; grid-template-columns: auto 1fr; column-gap: 8px; align-items: baseline; min-height: 36px; padding: 6px 8px; text-align: left; text-decoration: none; color: var(--fg); font-family: inherit; font-weight: 400; line-height: 1.35; text-transform: none; letter-spacing: normal; word-break: break-word; -webkit-tap-highlight-color: transparent; }
.msg .csrc b { grid-row: span 3; font: 600 11px var(--m); color: var(--c); }
.msg .csrc em { font: 10.5px var(--m); font-style: normal; color: var(--mute); word-break: break-all; }
.msg .csrc i { font-style: normal; font-size: 10.5px; color: #ffb3bd; }
.msg .csrc.miss { border-color: rgba(255,77,94,.5); border-style: dashed; }
.msg .citecheck { margin-top: 6px; color: var(--ok); white-space: normal; }
.msg .citecheck.warn { color: var(--a); }
.msg .citecheck span { text-transform: none; letter-spacing: 0; font: 11px var(--m); color: var(--mute); }
/* OWNER-ISSUES 77: a source's tier as a word in a small chip, and each claim's label in words after it; the word carries
   it (never colour alone), a dashed edge marks the weak ones (a lead, a host not known; contested, rumour, debunked) */
.msg .csrc .ctier { display: inline-block; margin-right: 2px; padding: 0 5px; border: 1px solid rgba(var(--cr), .5); border-radius: 4px; font: 600 9.5px/15px var(--m); letter-spacing: .06em; color: var(--fg); vertical-align: 1px; white-space: nowrap; }
.msg .csrc .ctier:is([data-tier="lead"], [data-tier="unknown"]) { border-style: dashed; border-color: rgba(var(--ar), .6); }
.msg .clabel { display: inline-block; padding: 0 6px; border: 1px solid rgba(var(--cr), .4); border-radius: 8px; font: 11px/16px var(--m); color: var(--mute); text-transform: none; white-space: nowrap; }
.msg .clabel:is([data-claim="contested"], [data-claim="rumour"], [data-claim="debunked"]) { border-style: dashed; border-color: rgba(var(--ar), .6); }
.pn.fresh .rw .ctier { display: inline-block; margin-right: 2px; padding: 0 5px; border: 1px solid rgba(var(--cr), .5); border-radius: 4px; font: 600 9.5px/15px var(--m); letter-spacing: .06em; color: var(--fg); vertical-align: 1px; white-space: nowrap; }
.pn.fresh .rw .ctier:is([data-tier="lead"], [data-tier="unknown"]) { border-style: dashed; border-color: rgba(var(--ar), .6); }
.citedoc blockquote { margin: 10px 0; padding: 8px 12px; border-left: 2px solid var(--c); background: rgba(var(--cr), .06); font-size: 14px; line-height: 1.5; }
.sitelink { display: flex; flex-direction: column; gap: 3px; min-height: 44px; padding: 12px 14px; text-decoration: none; color: inherit; -webkit-tap-highlight-color: transparent; }
.sitelink small { color: var(--c); text-transform: uppercase; }
.sitelink b { font-size: 15px; font-weight: 500; }
.sitelink span { opacity: .75; word-break: break-all; }
.site { display: flex; flex-direction: column; gap: 6px; padding: 6px 0; border-bottom: 1px solid var(--line2); }
.site .sitelink small { text-transform: none; letter-spacing: .02em; font: 400 10px var(--m); color: var(--mute); word-break: break-all; }
.sitelink:active { transform: scale(.98); }
/* a picture Ghosty made (or shared from the Lens), in the chat: the link shown as the picture */
.msg .piccard { display: block; max-width: 100%; margin: 6px 0 2px; text-decoration: none; -webkit-tap-highlight-color: transparent; }
.msg .piccard img { display: block; max-width: 100%; max-height: 320px; border-radius: 6px; border: 1px solid rgba(var(--cr), .45); background: rgba(var(--cr), .06); }
.msg .piccard:active img { transform: scale(.985); }
.approval { display: flex; flex-direction: column; }
.approval small { color: var(--a); text-transform: uppercase; }
.logbtn { display: inline-block; }
@media (max-width: 1239px) {
  .cside.l { display: flex; position: absolute; inset: 0 0 84px; z-index: 10; pointer-events: none; }
  .cside.l > .pn:not(.convo) { display: none; }
  .convo { display: none; flex: 1 1 0; }
  .hud.core.logopen .convo { display: flex; }
  .hud.core.logopen .rwrap, .hud.core.logopen #chips, .hud.core.logopen #ccap, .hud.core.logopen #cstate, .hud.core.logopen #glance, .hud.core.logopen .hudlayer { visibility: hidden; }
  .hud.core.logopen #chips { display: none; }
  .ccenter { z-index: 11; }
}
@media (min-width: 1240px) {
  .hud.core { grid-template-columns: 330px minmax(0, 1fr) 330px; gap: 14px; }
  .cside { display: flex; pointer-events: none; }
  /* Each side panel keeps room to read (a body of about 150 px: the pager fits two or three rows, a wrapped line is
     not squeezed); on a short window the column scrolls instead of starving its panels. */
  .cside > .pn { flex: 1 1 auto; min-height: 250px; }
  .cside.r { overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
  .logbtn { display: none; }
}
@media (max-width: 520px) { #cbar { flex-wrap: wrap; } #cbar button:not(#mic):not(#lensbtn) { flex: 1; } }

/* ---------- GOD'S EYE ---------- */
.hud.eye { grid-template-rows: auto minmax(0, 1fr) auto; }
.eyetop { position: relative; z-index: 2; display: flex; flex-direction: column; }
.eyetop > * { pointer-events: auto; }
.eyetop .search { display: flex; gap: 6px; }
.eyetop .search input { border-color: transparent; }
.eyetop .search input:focus { border-color: transparent; }
.modes { display: flex; }
.eyemid { position: relative; }
.labels { position: fixed; inset: 0; overflow: hidden; pointer-events: none; z-index: 0; }
.labels .lb { position: absolute; left: 0; top: 0; margin: -6px 0 0 8px; font: 400 9.5px var(--m); letter-spacing: .02em; text-shadow: 0 0 4px #000, 0 0 8px #000; white-space: nowrap; will-change: transform; }
.eyeinfo { position: absolute; left: 0; top: 0; width: min(310px, 66vw); max-height: 100%; }
.eyeinfo .bd { overflow-y: auto; }
.eyeinfo .row.wrap { gap: 5px; margin-top: 4px; } .eyeinfo .row.wrap button { padding: 5px 8px; min-height: 26px; font-size: 9px; }
.eyelay { position: absolute; right: 50px; top: 0; width: 300px; max-height: 100%; }
.eyelay .bd { overflow-y: auto; }
.lgroup { letter-spacing: .2em; }
.lgrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px; }
.ltile { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.ltile span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ltile em { color: var(--mute); letter-spacing: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; min-height: 11px; opacity: .8; text-transform: none; }
.ltile:hover { color: var(--fg); border-color: var(--line); }
.ltile.on em { color: var(--c); opacity: 1; }
@media (max-width: 699px) {
  /* phone: a sheet along the bottom of the globe, half the height at most, scrolling */
  .eyelay { max-height: 58%; }
  /* closed: a small LAYERS pill in the corner that opens the sheet */
  .eyelay.min > h3 small { display: none; }
  .eyelay.min > h3::after { color: var(--c); }
  .eyelay:not(.min) > h3::after { content: '▾'; font-size: 9px; color: var(--c); }
  .eyelay:not(.min) ~ .zoomrail { opacity: 0; pointer-events: none; }
  /* the open sheet is readable on its own: solid, and the camera grid under it steps aside */
  .eyelay:not(.min) { background: rgba(var(--bgr), .94); }
  .eyemid:has(.eyelay:not(.min)) .camgrid { display: none; }
  /* while the LOOK menu is up it has the corner: the LAYERS pill and the zoom rail step aside */
  /* (visibility, not pointer-events: #app .pn and #app button switch pointer-events back on) */
  .hud.eye:has(.lookmenu:not([hidden])) .eyelay.min, .hud.eye:has(.lookmenu:not([hidden])) .zoomrail { visibility: hidden; }
}
.zoomrail { position: absolute; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; align-items: center; pointer-events: auto; }
.zoomrail button { touch-action: none; }
.zoomrail small { text-align: center; max-width: 60px; }
.eyebot { position: relative; display: flex; align-items: flex-end; justify-content: space-between; }
.eyebot .readout { max-width: 60vw; overflow: hidden; }
.eyebot .btns { gap: 8px; flex-wrap: wrap; justify-content: flex-end; align-items: flex-end; pointer-events: auto; }
/* two groups: what to open about the spot under the crosshair, and how to move or draw the view */
.bgroup { display: flex; align-items: center; flex-wrap: wrap; }
.bcap { white-space: nowrap; }
/* the LOOK menu: tiles, sensor looks, sun and spin — above the bar, closed by LOOK, a tap on the globe or Escape */
.lookmenu { position: absolute; right: 0; bottom: 100%; margin-bottom: 6px; width: min(380px, 100%); display: flex; flex-direction: column; gap: 5px; padding: 8px 10px 10px; z-index: 6; pointer-events: auto; }
.lookmenu[hidden] { display: none; }
.lookmenu .chips { display: flex; gap: 3px; flex-wrap: wrap; }
.lookmenu .chips button, .modes button { min-height: 26px; }
.lookmenu .hint { font: 400 10px/1.4 var(--b); color: var(--mute); }
.eyebot .readout span { display: block; }
.eyebot .readout span:empty { display: none; }
@media (max-width: 600px) {
  .eyebot { flex-direction: column; align-items: stretch; }
  .eyebot .readout { max-width: 100%; }
  /* the live counts are in LAYERS already; the readout keeps where you are, the camera and the imagery credit */
  .eyebot .btns { justify-content: stretch; gap: 5px; }
  .bgroup { flex: 1 1 100%; }
  .bgroup button { flex: 1 1 auto; }
}

/* ---------- WORKSHOP ---------- */
.change { display: flex; flex-direction: column; gap: 6px; flex: none; }
.change.passed { border-left-color: var(--ok); background: rgba(79,227,168,.05); } .change.failed { border-left-color: var(--r); background: rgba(255,77,94,.05); }
.change .ct { display: flex; flex-direction: column; gap: 2px; } .change .ct small { letter-spacing: .14em; color: var(--mute); }
.change.failed .ct small { color: var(--r); } .change.passed .ct small { color: var(--ok); }
.change button { padding: 5px 8px; min-height: 26px; font-size: 9px; }
/* an upgrade idea Ghosty proposed for itself (Workshop → UPGRADE IDEAS) */
.idea { display: flex; flex-direction: column; gap: 6px; flex: none; min-width: 0; }
.idea b { overflow-wrap: anywhere; }
.idea ol { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 2px; font-size: 12px; line-height: 1.45; color: var(--mute); overflow-wrap: anywhere; }
.idea button { padding: 5px 8px; min-height: 26px; font-size: 9px; }
.idea .row small { margin-left: auto; font-size: 10px; }
#pg-workshop .pn > .bd, #pg-system .pn > .bd { overflow-y: auto; scrollbar-width: thin; }

@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }

/* keys onboarding */
.chip.good { border-color: rgba(79,227,168,.5); }
ol.steps { margin: 2px 0 4px 18px; padding: 0; font-size: 12.5px; line-height: 1.55; color: var(--fg); }
ol.steps li { margin: 3px 0; }
.note.good { color: var(--ok); } 
.pn.scroll > .bd { overflow-y: auto; }
.pn.models > .bd { max-height: 30vh; }

/* agenda */
.keyrow.wrapit { flex-wrap: wrap; }
.keyrow.wrapit > input { flex: 1 1 140px; min-width: 0; }
.keyrow.wrapit > select { flex: 0 1 auto; }
.keyrow.sub { margin: -2px 0 6px 0; gap: 8px; }
.keyrow.sub .note { font-size: 11px; }
.daylab { margin-top: 10px; color: var(--c); }
.rw.unread .v b { color: var(--ok); }
.suggest { margin-top: 6px; }
#dock button { position: relative; }
#dock button[data-badge]:not([data-badge=""])::after { content: attr(data-badge); position: absolute; text-align: center; padding: 0 3px; }
input[type="datetime-local"] { color-scheme: dark; }
.pn.feeds > .bd { max-height: 34vh; }

/* radio */
.nowplaying { max-width: 34vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-transform: none; }
.npstop { margin-left: 4px; }
input[type="range"] { flex: 1; }
.mnote { padding: 16px; font-size: 14px; line-height: 1.55; overflow-y: auto; } .mnote p { margin: 0 0 10px; } .mnote b { color: var(--a); font-weight: 500; }
#top .pausedtag { padding: 4px 8px; min-height: 0; }
#previewbar { position: fixed; left: 0; right: 0; bottom: 0; z-index: 90; padding: 6px 12px; background: rgba(255,178,62,.92); color: #120a00; font: 500 11px/1.4 var(--b); text-align: center; }

/* Pinch-zoom the page anywhere except on the globe, which uses pinch for its own zoom. */
body:not([data-scene="globe"]) #gl { touch-action: pan-x pan-y pinch-zoom; }
.rw .v { overflow-wrap: anywhere; }

/* Library tab */
.drop { display: flex; align-items: center; justify-content: center; text-align: center; cursor: pointer; }
.drop.on, .drop:hover, .drop:focus-visible { background: rgba(var(--cr), .1); border-style: solid; }
.liblog { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; }
.study .bar { margin: 4px 0; }
.study .bar span { max-width: 46%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.study .keyrow + .note { margin-top: 6px; }
.study .keyrow input { flex: 1 1 160px; min-width: 0; }
.readwrap { flex: 1; min-width: 0; display: flex; flex-direction: column; overflow: hidden; }
.reader { flex: 1; min-height: 0; overflow: auto; padding-right: 4px; -webkit-overflow-scrolling: touch; }
.study .bar b { min-width: 36px; white-space: nowrap; }
/* STUDY at scale */
.study .studynow { display: flex; margin: 2px 0 6px; border: 1px solid rgba(var(--cr), .35); }
.study .studynow > b { overflow-wrap: anywhere; }
.study .studypick, .study .studyallrow { margin: 6px 0; flex-wrap: wrap; }
.study .studypick select { max-width: 100%; text-overflow: ellipsis; }
.pn.study button, .pn.study .keyrow input { min-height: 44px; }
.study .studyallrow .note { min-width: 0; }
.study button.studyall { min-width: 150px; }
.study button.studyall[aria-checked="false"] { color: var(--mute); }
.study .studyfields { display: flex; }
.study .keyrow.wrapit > button { flex: 0 1 auto; }
/* end STUDY at scale */
.reader p { white-space: pre-wrap; word-break: break-word; }
.reader .note.bad { color: var(--r); }
.liblog .note.ok { color: var(--ok); }
.liblog .note.bad { color: var(--r); }
.rw.hit { flex-direction: column; align-items: flex-start; gap: 4px; }
.rw.hit .k { color: var(--c); white-space: normal; }
.rw.hit .v { white-space: normal; font-size: 12.5px; line-height: 1.5; }

/* Stark HUD around the reactor */
.hudlayer { position: absolute; inset: 0; pointer-events: none !important; z-index: 0; overflow: hidden; }
.ccenter > :not(.hudlayer) { position: relative; z-index: 1; }
canvas.starkhud { position: absolute; inset: 0; width: 100%; height: 100%; }
.callout { position: absolute; transform: translate(0, -50%); display: flex; flex-direction: column; gap: 2px; min-width: 110px; max-width: 190px; white-space: nowrap; }
.callout.l { transform: translate(-100%, -50%); text-align: right; }
.callout small { color: var(--mute); text-transform: uppercase; }
.callout b { letter-spacing: .02em; overflow: hidden; text-overflow: ellipsis; }
.callout[hidden] { display: none; }

/* God's Eye CCTV */
.camview { position: relative; background: #000; overflow: hidden; aspect-ratio: 16 / 10; }
.camview img, .camview video { width: 100%; height: 100%; object-fit: cover; display: block; filter: saturate(.9) contrast(1.05); }
.camview::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(0deg, rgba(0,0,0,.14) 0 1px, transparent 1px 3px); }
.camview.dead img { opacity: .25; }
.camstamp { position: absolute; left: 6px; top: 5px; z-index: 1; font: 400 8.5px var(--m); letter-spacing: .08em; color: #fff; text-shadow: 0 0 4px #000, 0 0 2px #000; }
.camrec { position: absolute; right: 7px; top: 7px; z-index: 1; width: 6px; height: 6px; border-radius: 50%; background: var(--r); animation: camrec 1.2s steps(2) infinite; }
@keyframes camrec { 50% { opacity: .15; } }
.camname { position: absolute; left: 0; right: 0; bottom: 0; z-index: 1; padding: 3px 6px; font: 400 8.5px var(--m); letter-spacing: .04em; color: #fff; background: linear-gradient(0deg, rgba(0,0,0,.85), transparent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.camgrid { position: absolute; left: 0; bottom: 0; width: min(380px, 70vw); }
/* ROAD AHEAD: what lies in front of the owner while they move (features/eye/roadahead.ts) */
.roadahead { position: absolute; left: 0; bottom: 0; width: min(360px, 70vw); max-height: 62%; z-index: 3; }
.roadahead .bd { overflow-y: auto; }
.roadahead .big { font: 600 22px var(--d); letter-spacing: .04em; color: var(--fg); display: flex; align-items: baseline; gap: 10px; padding: 2px 0 4px; }
.roadahead .big small { font: 500 10px var(--m); letter-spacing: .12em; color: var(--mute); }
.roadahead .lab { margin-top: 6px; }
.roadahead .rw.link { cursor: pointer; }
.roadahead .camlist .camview { margin: 4px 0; }
.roadahead small.dim { display: block; margin-top: 6px; font: 400 9.5px var(--m); color: var(--mute); }
.eyemid:has(.roadahead:not([hidden])) .camgrid { display: none; }
@media (max-width: 700px) { .roadahead { width: 68vw; max-height: 56%; } }
.camgrid .bd { display: grid; grid-template-columns: 1fr 1fr; }
.camgrid .camview { cursor: pointer; }
.camgrid .camview:hover { border-color: var(--c); }
.camgrid[hidden] { display: none; }
.eyeinfo .camview.big { margin-bottom: 6px; }
@media (max-width: 700px) { .camgrid { width: 62vw; } }

/* Training ground */
.trainnow { font: 400 10.5px var(--m); color: var(--c); min-height: 14px; margin: 6px 0; }

/* ---------- phone: one scrolling page instead of two swapped columns (page({ stack: true })) ---------- */
@media (max-width: 899px) {
  .two.stack { display: block; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; pointer-events: auto; }
  .two.stack > .cL, .two.stack > .cR { display: flex !important; overflow: visible; }
  .two.stack > .col > .pn { flex: none; min-height: 0; }
  .two.stack .swap { display: none; }
}
/* Columns of panels: a panel is at least as tall as what it holds (a long list stops at 70 % of the screen
   and scrolls there) and the column scrolls, rather than every panel squeezed to the same height with its
   own little scroll box — a button cut in half, a list in a slit. */
.col > .pn:not(.min) { flex: 1 0 auto; }
:where(.col > .pn) > .bd { max-height: max(70vh, 320px); } /* low specificity: a panel's own cap (.pn.models, .pn.feeds) still wins */
.stackf { display: flex; flex-direction: column; gap: 6px; }

/* ---------- Library: asking comes first ---------- */
.col > .pn.ask { flex: 1 1 auto; min-height: 300px; }
.askrow { padding: 10px 12px 2px !important; }
.trychips button { flex: 0 1 auto; white-space: normal; text-align: left; }
.pn.ask .rw.hit { padding: 8px 2px 10px; }
.pn.ask .rw.hit .v { -webkit-line-clamp: unset; display: block; }

/* ---------- systems deck ---------- */
#deck { position: fixed; inset: 0; z-index: 60; display: none; justify-content: center; padding: max(14px, env(safe-area-inset-top, 0)) 14px max(14px, env(safe-area-inset-bottom, 0)); }
#deck.on { display: flex; }
@keyframes deckin { from { opacity: 0; } }
.deckin { position: relative; width: min(920px, 100%); max-height: 100%; overflow-y: auto; overscroll-behavior: contain; display: flex; flex-direction: column; scrollbar-width: none; }
.dhead { display: flex; gap: 12px; }
.dtitle { display: flex; min-width: 0; }
.dtitle small { font: 400 10px var(--d); letter-spacing: .32em; color: rgba(var(--cr), .85); text-transform: uppercase; }
.dclock { flex-direction: column; align-items: flex-end; gap: 2px; }
.dclock b { font: 200 34px/1 var(--d); color: #fff; letter-spacing: .02em; }
.dclock span { font: 500 9px var(--d); letter-spacing: .24em; color: var(--mute); text-transform: uppercase; }
.dhead .sp { flex: 1; }
.dtiles { display: grid; }
.dtile { grid-template-columns: 28px minmax(0, 1fr); grid-template-rows: auto auto; text-align: left; text-transform: none; white-space: normal; }
.dtile .ic { grid-row: 1 / 3; fill: none; stroke-linecap: round; stroke-linejoin: round; }
.dtile small { font: 400 11px/1.35 var(--b); color: var(--mute); overflow: hidden; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.dtile:hover { background: rgba(var(--cr), .08); border-color: rgba(var(--cr), .4); }
.dtile:hover small { color: var(--fg); }
@keyframes dtin { from { opacity: 0; transform: translateY(6px); } }
.dquick { display: flex; flex-wrap: wrap; padding-top: 10px; }
.dquick button { flex: 1 1 150px; }
@media (max-width: 520px) {
  .dtile { grid-template-columns: 22px minmax(0, 1fr); }
  .dclock b { font-size: 26px; }
  .dquick button { flex: 1 1 40%; }
}
.eyeinfo small.dim { display: block; opacity: .6; font-size: 10px; margin: 6px 0 2px; }

/* ---------- Street View as if you were there (ui/streetview.ts): the panorama over the whole screen, under any sheet ---------- */
#street { position: fixed; inset: 0; z-index: 120; display: flex; flex-direction: column; background: #000; opacity: 0; transform: scale(1.06); transition: opacity .55s ease, transform .55s ease; pointer-events: none; }
#street.in { opacity: 1; transform: none; pointer-events: auto; }
.svbar { display: flex; align-items: center; gap: 6px; padding: calc(env(safe-area-inset-top, 0px) + 6px) 8px 6px; background: rgba(var(--bgr), .92); border-bottom: 1px solid var(--line); }
.svbar button { padding: 6px 8px; min-height: 0; font-size: 8.5px; white-space: nowrap; }
.svwhere { display: flex; flex-direction: column; min-width: 0; }
.svwhere b { font: 500 10px var(--d); letter-spacing: .16em; color: var(--c); text-transform: uppercase; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.svwhere small { font: 400 9px var(--m); letter-spacing: .1em; color: var(--mute); white-space: nowrap; }
.svframe { flex: 1 1 auto; min-height: 0; width: 100%; border: 0; background: #000; }
.svnote { padding: 5px 10px calc(env(safe-area-inset-bottom, 0px) + 6px); font: 400 10px/1.4 var(--b); color: var(--mute); background: rgba(var(--bgr), .92); border-top: 1px solid var(--line); }

/* ---------- the 3D map (ui/map3d.ts): MapLibre in Ghosty's colours ---------- */
.map3d { flex: 1 1 auto; min-height: 220px; position: relative; z-index: 0; background: #02070d; }
.map3d .maplibregl-canvas { outline: none; }
.map3d .maplibregl-ctrl-group { background: rgba(var(--bgr), .9); border: 1px solid var(--line); border-radius: 4px; box-shadow: none; }
.map3d .maplibregl-ctrl-group button { width: 30px; height: 30px; min-height: 0; padding: 0; border-color: var(--line2); }
.map3d .maplibregl-ctrl-group button + button { border-top: 1px solid var(--line2); }
.map3d .maplibregl-ctrl-attrib { background: rgba(var(--bgr), .8); color: var(--mute); font: 400 9px var(--b); max-width: 70%; text-align: right; }
.map3d .maplibregl-ctrl-attrib a { color: var(--mute); }
.map3d .maplibregl-ctrl-scale { background: rgba(var(--bgr), .7); border-color: var(--mute); color: var(--mute); font: 400 9px var(--m); }
.m3pin { position: relative; width: 18px; height: 26px; }
.m3pin i { position: absolute; left: 3px; bottom: 0; width: 12px; height: 12px; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); background: var(--a); border: 2px solid #fff; box-shadow: 0 0 8px var(--a); }
.m3pin.me i { background: var(--c); box-shadow: 0 0 10px var(--c); }
.m3pin span { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 2px; padding: 2px 6px; white-space: nowrap; font: 500 9px var(--d); letter-spacing: .1em; color: var(--c); background: rgba(var(--bgr), .9); border: 1px solid var(--line); border-radius: 3px; }
/* the pin popup above the map's own controls (its buttons can reach down to the scale bar on a phone) */
.maplibregl-popup.m3popup { z-index: 3; }
.m3popup .maplibregl-popup-content { background: rgba(var(--bgr), .96); color: var(--fg); border: 1px solid var(--line); border-radius: 6px; padding: 10px 12px; box-shadow: 0 8px 24px rgba(0, 0, 0, .5); }
.m3popup .maplibregl-popup-tip { border-top-color: var(--line); }
.m3popup .maplibregl-popup-close-button { color: var(--mute); font-size: 16px; padding: 2px 6px; }
.m3pop { display: flex; flex-direction: column; gap: 5px; max-width: 280px; }
.m3pop b { font: 500 10px var(--d); letter-spacing: .14em; color: var(--c); text-transform: uppercase; }
.m3addr { font: 400 11px/1.35 var(--b); color: var(--fg); }

/* ---- Lens (features/lens): the camera first, thumb-reachable controls, 44 px targets ---- */
.hud.lens { display: grid; grid-template-areas: 'view' 'modes' 'panel' 'bar' 'privacy'; grid-template-rows: auto auto minmax(0, 1fr) auto auto; pointer-events: auto; }
.hud.lens > * { pointer-events: auto; }
.lensview { grid-area: view; position: relative; width: 100%; aspect-ratio: 3 / 4; max-height: 44vh; background: #000; overflow: hidden; touch-action: manipulation; user-select: none; -webkit-user-select: none; }
.lensview video, .lensview canvas.lensstill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; background: #000; }
.lensview video.mirror { transform: scaleX(-1); }
.lensview canvas.lensov { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.lensstatus { position: absolute; z-index: 2; display: flex; align-items: center; }
.lensstatus span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lensstatus i { flex: none; border-radius: 50%; background: var(--mute); }
.lensstatus i.mid { animation: breath 1.4s ease-in-out infinite; } .lensstatus i.off { background: var(--r); }
.lensscene, .lenscount { position: absolute; bottom: 6px; z-index: 2; font: 400 9.5px var(--m); letter-spacing: .04em; color: #fff; text-shadow: 0 0 4px #000, 0 0 2px #000; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lensscene { left: 8px; max-width: 58%; } .lenscount { right: 8px; max-width: 38%; text-align: right; color: var(--a); }
.lensscene:empty, .lenscount:empty { display: none; }
.lensmodes { grid-area: modes; grid-auto-flow: column; grid-auto-columns: minmax(62px, 1fr); overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: none; }
.lensmodes::-webkit-scrollbar { display: none; }
.lensmodes button { flex-direction: column; justify-content: center; gap: 2px; }
.lensmodes button small { font: 400 8.5px var(--m); letter-spacing: 0; text-transform: none; color: var(--mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.lensmodes button.on small { color: var(--c); }
.lenspanel { grid-area: panel; min-height: 0; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; display: flex; flex-direction: column; scrollbar-width: thin; }
.lenspanel > .stackf { flex: none; }
.lenspanel .row button, .lenspanel .row.wrap button { flex: 1 1 auto; }
.lensbar { grid-area: bar; display: flex; }
.lensbar button { flex: 1 1 0; }
.lensprivacy { grid-area: privacy; text-align: center; }
.lenssel { display: flex; flex-direction: column; gap: 6px; }
.lenssel b { font: 500 12px var(--d); letter-spacing: .16em; color: var(--a); }
.lensocr { min-height: 120px; font: 400 13px/1.45 var(--b); }
.lensq { font: 400 15px/1.4 var(--b); min-height: 52px; }
.lensprog .bar { margin: 2px 0; }
.lensreply { white-space: pre-wrap; word-break: break-word; font-size: 13px; line-height: 1.5; }
.lensreply small { display: block; font: 500 8.5px var(--d); letter-spacing: .18em; color: var(--mute); text-transform: uppercase; margin-bottom: 3px; }
.lenschips { display: flex; gap: 4px; flex-wrap: wrap; }
.lenschips button { text-transform: none; }
/* NAME: the closest names, each a button with its share as a thin bar under the name */
.lensnames { display: flex; flex-direction: column; gap: 3px; }
.lensnames:empty { display: none; }
.lensnames button { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; min-height: 40px; padding: 6px 10px 8px; text-align: left; font: 400 13px var(--b); text-transform: none; letter-spacing: 0; }
.lensnames button span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lensnames button small { font: 500 10px var(--m); color: var(--c); letter-spacing: .06em; }
.lensnames button i { position: absolute; left: 10px; bottom: 4px; height: 2px; max-width: calc(100% - 20px); background: var(--c); opacity: .7; border-radius: 1px; }
.lensnames button.on { border-color: var(--a); } .lensnames button.on i { background: var(--a); }
.scansubs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.scansubs button { font: 500 10.5px var(--d); letter-spacing: .14em; text-transform: uppercase; min-height: 38px; padding: 6px 4px; }
.scancard { display: flex; flex-direction: column; gap: 7px; min-width: 0; }
.scancard > small { font: 500 9px var(--d); letter-spacing: .18em; color: var(--mute); }
.scanhead { display: flex; gap: 10px; align-items: flex-start; min-width: 0; }
.scanhead > div { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.scanimg { flex: none; width: 64px; height: 64px; object-fit: contain; background: #fff; border-radius: 4px; }
.scantitle { font: 500 15px/1.3 var(--b); color: #fff; overflow-wrap: anywhere; }
.scantext { font-size: 12px; line-height: 1.45; color: var(--mute); white-space: pre-wrap; overflow-wrap: anywhere; max-height: 9.5em; overflow-y: auto; }
.scankv { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 8px; font-size: 12.5px; align-items: baseline; }
.scankv b { font: 500 9px var(--d); letter-spacing: .14em; color: var(--c); }
.scankv span { overflow-wrap: anywhere; }
/* Lens MEASURE (features/lens/measure.ts) */
.measin { gap: 8px; } .measin input { flex: 1 1 80px; min-width: 0; max-width: 140px; } .measin .lab { margin: 0; white-space: nowrap; } .measin small { white-space: nowrap; }
.measguide { color: var(--c); font-size: 12.5px; }
.measlist { display: flex; flex-direction: column; gap: 4px; }
.measrow { display: grid; grid-template-columns: 20px minmax(0, auto) minmax(0, 1fr); gap: 2px 10px; align-items: baseline; padding: 6px 8px; border: 1px solid var(--line); border-radius: 6px; background: rgba(var(--cr), .05); }
.measrow b { font: 500 10px var(--d); color: var(--mute); }
.measrow .measv { font: 600 17px var(--d); color: var(--c); letter-spacing: .02em; white-space: nowrap; }
.measrow .measi { font-size: 12px; color: var(--mute); overflow-wrap: anywhere; }
.measrow small { grid-column: 2 / -1; font-size: 10.5px; color: var(--mute); line-height: 1.4; }
.measrow.rough .measv { color: var(--a); } .measrow.fair .measv { color: #ffd24d; }
/* SPACE PLANNER (features/space) */
.spacewrap { width: 100%; min-width: 0; display: flex; justify-content: center; padding: 4px 0; }
.spacecanvas { display: block; max-width: 100%; touch-action: none; user-select: none; -webkit-user-select: none; background: radial-gradient(ellipse at center, rgba(var(--cr), .06), transparent 70%); }
.spaceroom { flex-wrap: wrap; } .spaceroom input, .spacefitin input { flex: 1 1 60px; min-width: 0; max-width: 110px; } .spaceroom .x, .spacefitin .x { color: var(--mute); }
.spacefitin { flex-wrap: wrap; }
.spacebar { gap: 6px; } .spacebar .spacesel { flex: 1 1 160px; min-width: 0; font-size: 12px; color: var(--c); overflow-wrap: anywhere; }
.spaceown > input:first-child { flex: 2 1 120px; } 
.spaceopts button.spaceopt { display: block; width: 100%; text-align: left; text-transform: none; letter-spacing: 0; padding: 8px 10px; min-height: 44px; }
.spaceopt b { display: block; font: 500 10.5px var(--d); letter-spacing: .12em; color: var(--c); }
.spaceopt small { display: block; font-size: 11.5px; color: var(--mute); margin-top: 2px; overflow-wrap: anywhere; }
.spacemrow { gap: 6px; } .spacemrow > span { flex: 1 1 150px; min-width: 0; font-size: 12px; overflow-wrap: anywhere; } .spacemrow b { color: var(--c); }
/* LEARN tab (features/learn): courses with rings, the lesson reader, quiz choices, flashcards */
.learnring { width: 40px; height: 40px; flex: 0 0 40px; }
.learnring circle { fill: none; stroke-width: 2.5; stroke-linecap: round; } .learnring .track { stroke: rgba(var(--cr), .14); } .learnring .fg { stroke: var(--c); filter: drop-shadow(0 0 3px rgba(var(--cr), .6)); }
.learnring text { font: 400 9px var(--d); fill: #fff; }
button.learncourse, button.learnlesson { display: flex; align-items: center; gap: 10px; width: 100%; min-width: 0; min-height: 52px; padding: 6px 8px; margin: 0 0 6px; text-align: left; text-transform: none; letter-spacing: 0; white-space: normal; overflow: hidden; }
.learncinfo, .learnlesson > span, .learnhead > span { display: flex; flex-direction: column; min-width: 0; flex: 1 1 auto; }
.learncinfo b, .learnlesson b, .learnhead b { font: 500 12px var(--d); letter-spacing: .08em; color: var(--c); overflow-wrap: anywhere; }
.learncinfo small, .learnlesson small, .learnhead small { font-size: 11.5px; color: var(--mute); overflow-wrap: anywhere; margin-top: 2px; }
.learndue { color: var(--a); border-color: rgba(var(--ar), .5); flex: 0 0 auto; }
.learnlesson > i { flex: 0 0 26px; height: 26px; border: 1px solid rgba(var(--cr), .4); border-radius: 50%; display: grid; place-items: center; font: 500 11px var(--d); font-style: normal; color: var(--c); }
.learnlesson.done > i { background: rgba(var(--cr), .18); color: #fff; } .learnlesson.done b { color: var(--mute); }
.learnhead { display: flex; align-items: center; gap: 10px; margin: 2px 0 8px; }
.learnbar { gap: 6px; margin: 8px 0; }
button.learnbig { display: block; width: 100%; min-height: 54px; text-align: left; text-transform: none; letter-spacing: 0; margin: 0 0 8px; white-space: normal; }
.learnbig b { display: block; font: 500 11px var(--d); letter-spacing: .16em; color: var(--c); } .learnbig small { display: block; font-size: 12px; color: var(--mute); margin-top: 3px; overflow-wrap: anywhere; }
.learntopic input { flex: 1 1 auto; min-width: 0; }
.learnchips { gap: 4px; margin: 8px 0 0; align-items: center; flex-wrap: wrap; } 
.learntext { font-size: 14.5px; line-height: 1.6; color: #e6f8ff; overflow-wrap: anywhere; }
.learntext p { margin: 0 0 10px; } .learntext ul { margin: 0 0 10px; padding-left: 18px; } .learntext li { margin: 2px 0; }
.learnlead { font: 500 10px var(--d); letter-spacing: .16em; color: var(--c); }
sup.learncite { font: 500 9px var(--d); color: var(--c); padding: 0 2px; margin-left: 1px; border: 1px solid rgba(var(--cr), .35); border-radius: 2px; vertical-align: super; line-height: 1; }
.learnsources { display: flex; flex-wrap: wrap; gap: 4px; margin: 6px 0 10px; }
.learnsrc { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-transform: none; letter-spacing: .02em; font-size: 10px; text-decoration: none; color: var(--c); }
.learncheck { border-top: 1px solid rgba(var(--cr), .2); padding-top: 8px; margin-top: 4px; }
.learnq { font-size: 14.5px; line-height: 1.5; color: #fff; margin: 4px 0 8px; overflow-wrap: anywhere; }
button.learnchoice { display: block; width: 100%; min-height: 44px; margin: 0 0 6px; text-align: left; text-transform: none; letter-spacing: 0; font-size: 13.5px; white-space: normal; overflow-wrap: anywhere; }
button.learnchoice.good { border-color: var(--ok); background: rgba(79, 227, 168, .14); color: #fff; opacity: 1; }
button.learnchoice.bad { border-color: var(--r); background: rgba(255, 77, 106, .14); color: #fff; opacity: 1; }
.learnfeed { min-height: 1em; margin: 6px 0; } .learnfeed.good { color: var(--ok); } .learnfeed.bad { color: #ffb3c0; }
.learnshort input { flex: 1 1 auto; min-width: 0; }
.learnscore { text-align: center; padding: 16px 0 10px; } .learnscore b { display: block; font: 300 30px var(--d); letter-spacing: .08em; color: var(--c); text-shadow: 0 0 12px rgba(var(--cr), .5); } .learnscore small { display: block; color: var(--mute); font-size: 12.5px; margin-top: 6px; }
.learncard { min-height: 150px; padding: 14px 12px; margin: 0 0 8px; cursor: pointer; }
.learncard > small { display: block; font: 500 9px var(--d); letter-spacing: .18em; color: var(--mute); text-transform: uppercase; margin-bottom: 8px; }
.learnfront, .learnback { white-space: pre-wrap; overflow-wrap: anywhere; font-size: 15px; line-height: 1.5; color: #fff; }
.learnback { margin-top: 12px; padding-top: 10px; border-top: 1px dashed rgba(var(--cr), .35); color: var(--c); }
.learnrates { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
button.learnrate { min-height: 48px; padding: 4px 2px; } .learnrate > span { display: flex; flex-direction: column; align-items: center; } .learnrate b { font: 500 10px var(--d); letter-spacing: .1em; } .learnrate small { font-size: 10px; color: var(--mute); text-transform: none; letter-spacing: 0; margin-top: 2px; }
button.learnrate.again b { color: var(--r); } button.learnrate.hard b { color: var(--a); } button.learnrate.good b { color: var(--ok); } button.learnrate.easy b { color: var(--c); }
/* GYM tab (features/gym): game cards, the game's buttons, the mastery graph, a game's picture (grid / bars / lines) */
.gymcards { display: grid; }
button.gymcard { display: flex; min-width: 0; white-space: normal; }
.gymcard .gymname { overflow-wrap: anywhere; }
.gymcard small { letter-spacing: .04em; text-transform: none; }
.gymcard .gymspark { width: 100%; } .gymcard .spark { height: 18px; }
.gymlearns { overflow-wrap: anywhere; }
.gymstatus { margin: 0 0 8px; overflow-wrap: anywhere; } /* three lines kept free: a status that grows must not push the buttons under a finger */
