.gymactions button[hidden] { display: none; }
.gymgraph { width: 100%; display: block; }
.gymline { fill: none; } .gymgoal { vector-effect: non-scaling-stroke; }
.gymlevel { stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; } .gymgrid100 { vector-effect: non-scaling-stroke; }
.gymdetail { margin: 6px 0 8px; overflow-wrap: anywhere; }
