@media (max-width: 409px) { html .hud.core #suggest .sugg .ic { display: none; } html .hud.core #suggest > button { padding: 0 10px; } }
/* the ask bar (Home) and the composer (Chat): one glass capsule; the field, the chat button, the microphone */
html .hud.core #cbar { position: sticky; bottom: 0; z-index: 6; display: flex; align-items: center; gap: 2px; flex: none; width: auto; height: 52px; margin: 10px 0 0; padding: 0 6px 0 4px; border-radius: 26px; background: rgba(34,37,41,.72); box-shadow: inset 0 0 0 1px var(--hair2), inset 0 1px 0 rgba(255,255,255,.06), 0 12px 30px rgba(0,0,0,.35); -webkit-backdrop-filter: blur(24px) saturate(1.6); backdrop-filter: blur(24px) saturate(1.6); }
html .hud.core #cbar > :not(.plusmenu) { grid-column: auto; grid-row: auto; margin: 0; justify-self: auto; }
html .hud.core #cbar > button { flex: none !important; }
html .hud.core #cbar #cin { order: 0; flex: 1 1 0; min-width: 0; height: 44px; min-height: 44px; padding: 0 8px 0 10px; font: 400 17px var(--sf); letter-spacing: -.25px; color: var(--ink); background: none !important; box-shadow: none !important; -webkit-backdrop-filter: none; backdrop-filter: none; border-radius: 0; }
html .hud.core #cbar #cin:not(:placeholder-shown) { padding: 0 8px 0 10px; }
