html .hud.core #cbar #mic { position: relative; flex: none; width: 40px; height: 40px; min-height: 40px !important; border-radius: 20px; background: linear-gradient(180deg, color-mix(in srgb, var(--c) 58%, #fff), color-mix(in srgb, var(--c) 88%, #000)); box-shadow: 0 0 0 1px rgba(var(--cr), .35), 0 4px 16px rgba(var(--cr), .28); }
