html .hud.core #cbar .sendbtn { display: none !important; position: relative; flex: none; width: 40px; height: 40px; min-height: 40px !important; border-radius: 20px; background: linear-gradient(180deg, color-mix(in srgb, var(--c) 58%, #fff), color-mix(in srgb, var(--c) 88%, #000)); }
