/* its offer when the phone could not do a task kept on it: ASK THE BIG BRAIN, a full-size target */
.msg.err .bigbrain { min-height: 44px; }
@media (max-width: 899px) {
  html body.tabbar #dock.areas { padding-bottom: max(12px, calc(env(safe-area-inset-bottom, 0px) - 6px)); }
  html body.tabbar .hud.core { padding-bottom: calc(64px + 20px + max(12px, calc(env(safe-area-inset-bottom, 0px) - 6px))); }
}
@media (min-width: 900px) {
  html .hud.core > .ccenter > :is(.rcwx, .rcbelow, #suggest, #cbar, #ccap) { width: 100%; max-width: 440px; align-self: center; }
}

