/* LEVELS BY GAME, TRAIN ALL and KEEP AWAKE: one glass card */
html #pg-gym .gymall { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 0 10px; margin: 6px 0 0; padding: 16px; border-radius: 20px; background: var(--rcglass); box-shadow: var(--edge), var(--lift); -webkit-backdrop-filter: blur(28px) saturate(1.6); backdrop-filter: blur(28px) saturate(1.6); }
