html #pg-gym .gymall .gymswitch .bic { display: block; line-height: 0; }
html #pg-gym .gymall .gymswitch .bic .ic { width: 18px; height: 18px; fill: none; stroke: var(--ink2); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
html #pg-gym .gymall .gymswtxt { display: block; }
html #pg-gym .gymall .gymswtxt b[data-label]::before { --lfs: 15px; font-weight: 500; white-space: nowrap; }
