html #pg-gym .gymall .gymswitch:disabled { opacity: .55; }
html #pg-gym .gymallst { grid-column: 1 / -1; position: relative; margin-top: 12px; padding-left: 15px; font: 400 13px/18px var(--sf); color: var(--ink2); }
html #pg-gym .gymallst::before { content: ''; position: absolute; left: 0; top: 6px; width: 7px; height: 7px; border-radius: 4px; background: var(--ink3); }
html #pg-gym .gymall:has(.gymallbtn[data-label="Stop"]) .gymallst::before { background: var(--c); box-shadow: 0 0 8px var(--c); }
@media (max-width: 400px) { html #pg-gym .gymall { grid-template-columns: minmax(0, 1fr); } html #pg-gym .gymall button.gymswitch { grid-column: 1; justify-content: space-between; margin-top: 10px; } }
/* Games: a heading, then a card each — the game's picture (features/gym/art.ts), its state, name and level, the mastery meter with the pass mark, his rating or the next level's mark (styled in "Iron Man" below) */
html #pg-gym .gymsec { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin: 34px 0 10px; }
html #pg-gym .gymsec b { font: 700 22px/28px var(--sfd); letter-spacing: -.3px; color: var(--ink); }
html #pg-gym .gymsec span { font: 400 13px var(--sf); color: var(--ink3); white-space: nowrap; }
html #pg-gym .gymcards { gap: 12px; }
html #pg-gym .gymcard .gymrate[hidden], html #pg-gym .gymcard .gymnext[hidden] { display: none; }
.gymideas { display: flex; flex-direction: column; gap: 10px; margin: 4px 0 14px; }
.gymideas[hidden] { display: none; }
.gymidea { display: flex; flex-direction: column; gap: 3px; padding: 12px 14px; border-radius: 16px; background: rgba(255,255,255,.05); box-shadow: inset 0 0 0 1px rgba(255,255,255,.08); overflow-wrap: anywhere; }
.gymidea b { font: 600 15px/1.3 var(--sf); color: var(--fg); }
.gymidea .gymrateline, .gymidea .gymedgeline { font: 500 16px/1.35 var(--sf); color: var(--fg); }
.gymidea small { font: 400 13px/1.4 var(--sf); color: var(--l2); }
.gymidea small.thrown { color: #ff9f0a; }
.gymsays { display: flex; flex-direction: column; gap: 4px; margin: 0 0 12px; overflow-wrap: anywhere; } /* Connect 4: what he says about your games (gym2) */
.gymsays[hidden] { display: none; }
.gymsays b { font: 500 17px/1.38 var(--sf); letter-spacing: -.01em; color: var(--fg); }
.gymsays small { font: 400 14px/1.4 var(--sf); color: var(--l2); }
.gymreview { display: flex; flex-direction: column; gap: 7px; max-width: 360px; margin: 12px auto 0; padding: 12px 14px; border-radius: 16px; background: rgba(255,255,255,.05); box-shadow: inset 0 0 0 1px rgba(255,255,255,.08); overflow-wrap: anywhere; }
.gymreview > b { font: 600 13px/1.3 var(--sf); color: var(--l2); }
.gymreview > div { display: flex; gap: 10px; font: 400 15px/1.4 var(--sf); color: var(--fg); }
.gymreview > div span { flex: none; min-width: 62px; color: var(--l2); font-variant-numeric: tabular-nums; }
.gymreview > div i { font-style: normal; min-width: 0; }
html #pg-gym .gymcard .gymsay { display: block; margin-top: 5px; font: 500 12px/15px var(--sf); letter-spacing: 0; text-transform: none; color: var(--ink2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } /* Connect 4: his line about your games */

/* ---------- Settings, System and Links (ui/listmode.ts): grouped glass rows — a neutral icon tile, the name,
   its line under it, a chevron ---------- */
html .lcard { border-radius: 20px; background: rgba(255,255,255,.05); box-shadow: inset 0 0 0 1px var(--hair); -webkit-backdrop-filter: blur(24px); backdrop-filter: blur(24px); }
html .lgt { margin: 0 16px 8px; font: 600 11px/13px var(--sf); letter-spacing: .09em; text-transform: uppercase; color: var(--ink3); }
html .lgf { font: 400 13px/18px var(--sf); color: var(--ink3); }
html .listmode .pn[data-row] > h3 { display: grid; grid-template-columns: 36px minmax(0, 1fr) 16px; grid-template-rows: auto auto; column-gap: 14px; row-gap: 0; align-content: center; min-height: 60px; padding: 9px 14px 9px 12px; }
html .listmode .pn[data-row] > h3 > :is(.light, .sp) { display: none; }
html #app .listmode .pn[data-row] > h3 > .rowic { grid-column: 1; grid-row: 1 / 3; align-self: center; width: 36px; height: 36px; border-radius: 10px; background: rgba(255,255,255,.08) !important; box-shadow: inset 0 0 0 1px var(--hair) !important; }
html #app .listmode .pn[data-row] > h3 > .rowic .ic { width: 20px; height: 20px; stroke: var(--ink) !important; stroke-width: 1.7; }
html .listmode .pn[data-row] > h3 > .ptitle { grid-column: 2; grid-row: 1; align-self: end; font: 500 17px/22px var(--sf); letter-spacing: -.25px; color: var(--ink); }
html .listmode .pn[data-row] > h3 > small { grid-column: 2; grid-row: 2; align-self: start; max-width: none; text-align: left; font: 400 13px/17px var(--sf); color: var(--ink3); white-space: normal; }
html .listmode .pn[data-row] > h3 > small[data-label]::before { --lfs: 13px; }
html .listmode .pn[data-row] > h3 > small:empty:not([data-label]), html .listmode .pn[data-row] > h3 > small[data-label=""] { display: none; }
html .listmode .pn[data-row] > h3:has(> small:empty:not([data-label])) > .ptitle, html .listmode .pn[data-row] > h3:has(> small[data-label=""]) > .ptitle { grid-row: 1 / 3; align-self: center; }
html .listmode .pn[data-row] > h3 > .chev { grid-column: 3; grid-row: 1 / 3; align-self: center; width: 8px; height: 8px; margin: 0 4px 0 0; border-color: var(--ink4); }
html .lcard > .pn + .pn:not(.pushed) > h3::before { left: 62px; height: 1px; background: var(--hair); }
html .listmode .col > .keepcard { background: var(--rcglass); box-shadow: var(--edge), var(--lift); border-radius: 20px; }
html .listmode .keepcard .rw { padding: 10px 0; border-bottom: 1px solid var(--hair); }
html .listmode .keepcard .rw .k, html .listmode .keepcard .rw .v { font: 400 15px/20px var(--sf); letter-spacing: -.12px; }
html .listmode .keepcard .rw .k { color: var(--ink2); }
html .listmode .keepcard .rw .v { color: var(--ink); }
html .listmode .keepcard .rw .k[data-label] { --lfs: 15px; }

/* ---------- WHAT'S NEW (features/workshop, state/whatsnew.ts) and the way back to an old look (Settings → Look) ---------- */
.wnrow { display: flex; flex-direction: column; gap: 2px; }
html .whatsnew .wnrow { padding: 10px 0; border-bottom: 1px solid var(--hair); }
html .whatsnew .wnrow b { font: 600 17px/22px var(--sf); letter-spacing: -.25px; color: var(--ink); }
html .whatsnew .wnrow span { font: 400 15px/20px var(--sf); letter-spacing: -.12px; color: var(--ink2); }
/* ---------- Iron Man (BRIEF-IRON-BUILD; the owner's pick, OWNER-ISSUES 41 and 43): A's instruments with C's restraint,
   and MIND's hologram (not a reactor: the owner, 24 Oct) at the centre. MIND's light in every card: a lit top edge, the instruments in thin glowing line (ui/
   instruments.ts, features/gym/art.ts), readouts in an instrument face, one thin scan line that crosses an instrument
   once as its hub opens; no corner brackets, no grid backdrop, labels 11 px or more. Every colour is the theme's
   (--c, --cr, --c2), so Graphite draws the same shapes in steel. Nothing moves when the phone asks for less (the
   reduced-motion rule above stops every animation and transition). ---------- */
html { --mono: ui-monospace, 'SF Mono', SFMono-Regular, Menlo, monospace; --hud: rgba(var(--cr), .22); --hud2: rgba(var(--cr), .1); }
html :is(.tnum, .hubtile .rd b, .rcmeta b, .gymcard .gymrl, .gymcard .gymlvl) { font-variant-numeric: tabular-nums slashed-zero; }

/* the instrument card: dark glass lit from its top edge, a soft glow of MIND's light round it */
html .hubtile.inst, html #pg-gym button.gymcard, html .hud.core .convo .msg.latest:not(.me) {
  background: linear-gradient(180deg, rgba(var(--cr), .085), rgba(var(--cr), .018) 38%, rgba(6,10,13,.82) 100%), rgba(8,12,15,.7) !important;
  box-shadow: inset 0 0 0 1px var(--hud), inset 0 1px 0 rgba(var(--cr), .38), 0 0 30px -12px rgba(var(--cr), .4), 0 18px 40px rgba(0,0,0,.55) !important;
}
html .hubgrid { gap: 12px; }
html .hubtile.inst { position: relative; display: flex; flex-direction: column; align-items: stretch; gap: 0; min-width: 0; min-height: 44px; padding: 12px 13px 12px; overflow: hidden; isolation: isolate; text-align: left; border-radius: var(--card); transition: transform var(--rcsp) var(--spring), box-shadow .3s; }
html .hubtile.inst > * { position: relative; z-index: 2; }
html .hubtile.inst:active { transform: scale(.975); box-shadow: inset 0 0 0 1px rgba(var(--cr), .55), inset 0 1px 0 rgba(var(--cr), .6), 0 0 40px -8px rgba(var(--cr), .6), 0 18px 40px rgba(0,0,0,.55) !important; }
html .hubtile.inst:focus-visible { outline: 2px solid var(--c); outline-offset: 2px; }
/* the kicker: bare glyph, the name, the live dot and one word */
html .hubtile .kick { order: 2; display: flex; align-items: center; gap: 6px; margin-top: 2px; font: 600 11px/14px var(--mono); letter-spacing: .1em; text-transform: uppercase; color: rgba(var(--cr), .85); white-space: nowrap; }
html .hubtile .kick .ic { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
html .hubtile .kick .nm { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
html .hubtile .kick .st { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; font-style: normal; color: var(--c2); text-shadow: 0 0 8px rgba(var(--cr), .8); }
html .hubtile .kick .st .dot { width: 6px; height: 6px; border-radius: 3px; background: currentColor; flex: none; }
html .hubtile:is([data-status="ready"], [data-status="off"]) .kick .st { color: rgba(var(--cr), .5); text-shadow: none; }
html .hubtile[data-status="off"] .kick .st .dot { background: transparent; box-shadow: inset 0 0 0 1px currentColor; }
html .hubtile .dot.pulse { box-shadow: 0 0 0 3px rgba(var(--cr), .18), 0 0 8px var(--c); animation: ironbreathe 2.4s ease-in-out infinite; }
@keyframes ironbreathe { 50% { box-shadow: 0 0 0 5px rgba(var(--cr), .06), 0 0 12px var(--c); } }
html .hubtile .t { order: 3; margin-top: 4px; font: 600 16px/21px var(--sf); letter-spacing: -.25px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* the readouts: an instrument face */
html .hubtile .reads { order: 5; display: grid; grid-template-columns: 1fr 1fr; gap: 8px 10px; margin-top: 9px; padding-top: 9px; border-top: 1px dashed rgba(var(--cr), .18); }
html .hubtile .rd { display: flex; flex-direction: column; min-width: 0; }
html .hubtile .rd em { font: 600 11px/13px var(--mono); font-style: normal; letter-spacing: .06em; text-transform: uppercase; color: rgba(var(--cr), .55); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html .hubtile .rd b { margin-top: 2px; font: 500 17px/22px var(--mono); letter-spacing: -.3px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html .hubtile .rd b small { display: inline; margin-left: 4px; font: 500 11px/1 var(--sf); letter-spacing: 0; color: var(--ink2); }
html .hubtile .rd.lv b { color: var(--c2); text-shadow: 0 0 10px rgba(var(--cr), .55); }
html .hubtile .rd.none b { font: 500 14px/22px var(--sf); color: var(--ink3); }
html .hubtile .why { order: 6; margin-top: 5px; font: 400 12px/15px var(--sf); color: var(--ink3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html .hubtile .why[hidden] { display: none; }
/* the instrument: across the top of a half card, at the left of a wide one; a thin scan line crosses it once */
html .hubtile .ins { order: 1; position: relative; display: grid; place-items: center; height: 72px; margin: -2px -3px 6px; border-radius: 12px; background: radial-gradient(ellipse 60% 70% at 50% 50%, rgba(var(--cr), .12), transparent 70%); overflow: hidden; }
html .hubtile .ins[hidden] { display: none; }
html .hubgrid:not(:has(> :nth-child(5))) .hubtile .ins { height: 100px; }
html .hubgrid:not(:has(> :nth-child(5))) .hubtile .ins > :is(svg, .insc > svg) { height: 100px; }
html .hubtile .ins > svg, html .hubtile .ins > .insc > svg { width: 100%; height: 72px; }
html .hubtile .ins svg.i-trace, html .hubtile .ins svg.i-count, html .hubtile .ins svg.i-day { width: 70%; height: 54px; }
/* a hub of five or more: shorter instruments, so three rows show before the hub scrolls (it scrolls since 1 Nov: every tool
   of the area is a card, the owner's word on findability, BRIEF-TABS 3; the line under the title wraps rather than is cut) */
html .hubgrid:has(> :nth-child(5)) .hubtile .ins { height: 52px; }
html .hubgrid:has(> :nth-child(5)) .hubtile .ins > :is(svg, .insc > svg) { height: 52px; }
