html .hubtile .ins::after { content: ''; position: absolute; left: 0; right: 0; top: 0; height: 1px; z-index: 3; pointer-events: none; opacity: 0; background: linear-gradient(90deg, transparent, rgba(var(--cr), .8), transparent); box-shadow: 0 0 10px rgba(var(--cr), .6); }
html .pg.on .hubtile .ins::after { animation: ironscan 1.6s var(--spring) .15s 1 both; }
@keyframes ironscan { 0% { opacity: 0; transform: translateY(0); } 12% { opacity: 1; } 88% { opacity: .8; } 100% { opacity: 0; transform: translateY(72px); } }
html .hubtile .insc, html .hubtile .ctr { position: relative; display: grid; place-items: center; width: 100%; height: 100%; }
html .hubtile .ctr { position: absolute; inset: 0; text-align: center; }
html .hubtile .ctr b { display: block; font: 500 22px/24px var(--mono); letter-spacing: -.4px; color: #fff; text-shadow: 0 0 12px rgba(var(--cr), .7); }
