html .hubtile .ctr small { display: block; font: 600 11px/13px var(--mono); letter-spacing: .12em; text-transform: uppercase; color: rgba(var(--cr), .6); }
html .hubtile .coursemap { display: flex; flex-direction: column; align-items: center; gap: 8px; max-width: 100%; padding: 0 8px; }
html .hubtile .coursemap .cmk { font: 600 11px/13px var(--mono); letter-spacing: .12em; text-transform: uppercase; color: rgba(var(--cr), .6); }
html .hubtile .coursemap .cm { max-width: 100%; font: 600 15px/18px var(--sf); color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html .segs { display: grid; gap: 4px; width: 150px; max-width: 100%; }
html .segs i { height: 5px; border-radius: 1px; background: rgba(var(--cr), .14); }
html .segs i.on { background: var(--c); box-shadow: 0 0 8px rgba(var(--cr), .8); }
html .segs i.live { background: var(--c2); box-shadow: 0 0 10px var(--c); }
html .hubtile .lensvf { position: relative; display: grid; place-items: center; width: 100%; height: 100%; }
html .hubtile .lensvf svg { width: 100%; height: 100%; }
html .hubtile .lensvf .vfcap { position: absolute; left: 0; right: 0; bottom: 6px; text-align: center; font: 600 11px/13px var(--mono); letter-spacing: .14em; text-transform: uppercase; color: rgba(var(--cr), .6); }

/* ---------- the instruments' line work (scoped to svg.inst: nothing else in the app is touched) ---------- */
html svg.inst { display: block; overflow: visible; }
