html svg.inst .gl { opacity: .7; }
html svg.inst .vf-brk { fill: none; stroke: var(--c); stroke-width: 1.6; stroke-linecap: round; filter: url(#ig-glow); }
html svg.inst .m-l { fill: none; stroke: rgba(var(--cr), .2); stroke-width: .5; }
html svg.inst .m-l.lit { stroke: rgba(var(--cr), .6); stroke-width: .6; filter: none; }
html svg.inst .m-n { fill: rgba(var(--cr), .4); }
html svg.inst .m-n.on { fill: var(--c2); filter: url(#ig-glow); }
html svg.inst .sg { fill: none; stroke: rgba(var(--cr), .15); stroke-width: 5; }
html svg.inst .sg.on { stroke: var(--c); filter: url(#ig-glow); }
html svg.inst .sg.live { stroke: var(--c2); stroke-dasharray: 2 1.4; filter: url(#ig-glow); }
html svg.inst.i-count .sg { stroke-width: 3; }
html svg.inst.i-trace.dn .lit { stroke: var(--amber); } html svg.inst.i-trace.dn .fl { fill: var(--amber); }
html svg.inst .ctx { font: 600 9px var(--mono); fill: var(--c2); text-anchor: middle; }
html svg.inst .gy-rim { fill: rgba(var(--cr), .16); stroke: var(--c); stroke-width: 1.1; filter: url(#ig-glow); }
html svg.inst .gy-eq { fill: none; stroke: var(--c2); stroke-width: .6; }
/* the GYM's pictures */
html svg.inst .mv { stroke: var(--c2); stroke-width: 1; stroke-dasharray: 2.5 2; filter: url(#ig-glow); }
html svg.inst .tgt { stroke: var(--c2); stroke-width: .9; filter: url(#ig-glow); }
html svg.inst .path { stroke: var(--c); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; filter: url(#ig-glow); opacity: .95; }
html svg.inst .dg { font: 500 5.6px var(--mono); fill: rgba(var(--cr), .55); text-anchor: middle; }
html svg.inst .dg.his { fill: var(--c2); font-weight: 700; filter: url(#ig-glow); }
html svg.inst .dg.big { font-size: 11px; }
html svg.inst .hl { fill: rgba(var(--cr), .06); }
html svg.inst .cur { fill: rgba(var(--cr), .22); stroke: var(--c2); stroke-width: .8; filter: url(#ig-glow); }
html svg.inst .edge { stroke: rgba(var(--cr), .5); stroke-width: .6; }
html svg.inst :is(.disc.his, .stone.his) { fill: var(--c); filter: url(#ig-glow); }
html svg.inst .disc.opp { fill: none; stroke: rgba(var(--cr), .7); stroke-width: .9; }
html svg.inst .hole { fill: none; stroke: rgba(var(--cr), .16); stroke-width: .6; }
html svg.inst .win { stroke: #fff; stroke-width: 1; filter: url(#ig-glow); }
html svg.inst .trail { stroke: rgba(var(--cr), .5); stroke-width: 1.4; stroke-linecap: round; }
