html #pg-gym button.gymcard.on { box-shadow: inset 0 0 0 1px rgba(var(--cr), .6), inset 0 1px 0 rgba(var(--cr), .6), 0 0 36px -10px rgba(var(--cr), .6), 0 18px 40px rgba(0,0,0,.55) !important; }
html #pg-gym .gymcard svg.gymart { width: 100%; height: 78px; margin: 0 0 5px; border-radius: 10px; background: radial-gradient(ellipse 70% 60% at 50% 100%, rgba(var(--cr), .2), transparent 75%); }
