html #pg-gym .gymcard .gymst { position: absolute; right: 10px; top: 9px; display: inline-flex; align-items: center; gap: 5px; padding: 2px 7px 2px 6px; border-radius: 6px; font-style: normal; color: rgba(var(--cr), .55); background: rgba(5,8,10,.7); }
html #pg-gym .gymcard .gymst::after { content: ''; order: -1; width: 5px; height: 5px; border-radius: 3px; background: currentColor; }
