html #pg-gym .gymcard .gymst:is(.new, .paused) { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
html #pg-gym .gymcard .gymnm { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
html #pg-gym .gymcard .gymname { display: block; min-width: 0; font: 600 16px/20px var(--sf); letter-spacing: -.25px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html #pg-gym .gymcard .gymlvl { display: block; flex: none; font: 600 11px/14px var(--mono); letter-spacing: .12em; color: rgba(var(--cr), .75); }
html #pg-gym .gymcard .meter { position: relative; height: 5px; margin-top: 7px; border-radius: 1px; background: rgba(var(--cr), .12); }
html #pg-gym .gymcard .meter i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 1px; background: linear-gradient(90deg, rgba(var(--cr), .45), var(--c)); box-shadow: 0 0 8px rgba(var(--cr), .7); transition: width .6s var(--spring); }
html #pg-gym .gymcard .meter u { position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; border-radius: 1px; background: #fff; box-shadow: 0 0 6px #fff; }
