html #pg-gym .gymcard .gymrl { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; margin-top: 6px; font: 500 11px/14px var(--mono); color: rgba(var(--cr), .6); white-space: nowrap; }
html #pg-gym .gymcard .gymrl :is(.gymrate, .gymnext) { display: block; min-width: 0; margin: 0; font: 500 11px/14px var(--mono); letter-spacing: 0; color: rgba(var(--cr), .6); overflow: hidden; text-overflow: ellipsis; }
html #pg-gym .gymcard .gymrl .gymrate { font: 500 12px/14px var(--sf); letter-spacing: 0; text-transform: none; color: var(--ink2); }
html #pg-gym .gymcard .gymrl .gympct { flex: none; font-weight: 500; color: var(--c2); }

/* ---------- the reply card: Ghosty's glyph, the meta line, the claims readout ---------- */
html .rcwho b { font: 600 11px/16px var(--mono); letter-spacing: .12em; text-transform: uppercase; color: #fff; }
html .rcwho em { font: 500 11px/16px var(--mono); color: rgba(var(--cr), .6); }
