html .rcmeta { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 2px 0 2px; padding-bottom: 7px; border-bottom: 1px dashed rgba(var(--cr), .16); font: 500 11px/14px var(--mono); letter-spacing: .04em; color: rgba(var(--cr), .5); }
html .rcmeta b { font-weight: 500; letter-spacing: 0; color: var(--c2); }
html .rcclaims { display: flex; align-items: center; gap: 10px; margin-top: 12px; padding: 8px 10px; border-radius: 14px; background: rgba(var(--cr), .05); box-shadow: inset 0 0 0 1px var(--hud2); }
html .rcclaims svg.i-claims { width: 30px; height: 30px; flex: none; }
html .rcclaims .citecheck { margin: 0; }
html .rcclaims.warn svg.i-claims .sg:not(.on) { stroke: rgba(var(--amberr), .45); }

/* ---------- the floating tab bar: the lit tab in a small ring of light, the live dot, the badge as an alert ring ---------- */
html #dock .tabcap { background: rgba(7,11,14,.78); box-shadow: inset 0 0 0 1px var(--hud), 0 0 34px -12px rgba(var(--cr), .55), 0 20px 50px rgba(0,0,0,.6); }
html #dock .tabcap::before { content: ''; position: absolute; left: 30px; right: 30px; top: 0; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgba(var(--cr), .7), transparent); }
html body #dock .tabcap button { font: 600 11px/13px var(--sf) !important; color: rgba(235,240,245,.6); }
html #dock .tabcap button.on { color: var(--c); background: none; box-shadow: none; }
html #dock .tabcap .gi { position: relative; display: grid; place-items: center; width: 30px; height: 28px; font-style: normal; }
html #dock .tabcap .gi .halo { position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; margin: -21px 0 0 -21px; border-radius: 50%; opacity: 0; transform: scale(.8); }
html #dock .tabcap button.on .gi .halo { opacity: 1; transform: none; background: radial-gradient(circle, rgba(var(--cr), .28), transparent 62%); box-shadow: inset 0 0 0 1px rgba(var(--cr), .35), 0 0 0 4px rgba(var(--cr), .05), 0 0 0 5px rgba(var(--cr), .18); }
html #dock .tabcap button.on .ic { filter: drop-shadow(0 0 5px rgba(var(--cr), .9)); }
html #dock .tabcap button.on .gi::before { content: ''; position: absolute; top: -11px; left: 50%; width: 18px; height: 2px; margin-left: -9px; border-radius: 1px; background: var(--c); box-shadow: 0 0 8px var(--c); }
html #dock .tabcap button:active .gi .halo { opacity: 1; transform: scale(1.08); transition: transform var(--rcsp) var(--spring); background: radial-gradient(circle, rgba(var(--cr), .45), transparent 65%); box-shadow: inset 0 0 0 1.5px rgba(var(--cr), .7), 0 0 0 6px rgba(var(--cr), .08), 0 0 22px rgba(var(--cr), .5); }
html #dock .tabcap button:active { color: #fff; }
html #dock .tabcap .gi .live { position: absolute; top: 1px; right: 0; width: 8px; height: 8px; border-radius: 4px; display: none; background: var(--c); box-shadow: 0 0 0 2.5px rgba(7,11,14,1), 0 0 0 3.5px rgba(var(--cr), .5), 0 0 10px var(--c); }
