/* hero: mind — Home's 3-D centrepiece (features/core/mind.ts); its light is the theme's accent. Its WebGL canvas lies exactly over
   the 2-D reactor's canvas, which keeps its place in the layout (and its taps) but is not drawn while Mind runs. */
.rwrap:has(> canvas.mindhero) { position: relative; }
canvas.mindhero { position: absolute; left: 0; top: 0; display: block; pointer-events: none; }
canvas.reactor.mindon { opacity: 0; }
/* the brain gone: the old 2-D stand-in and the flat Mind go low too (orbsay.ts says why under it) */
canvas.reactor[data-low="1"]:not(.mindon) { opacity: .5; }
canvas.mindhero.lowlight { opacity: .45; transition: opacity var(--g-dur-turn, .4s); }
/* the orb's one line under it: said once, then gone (features/core/orbsay.ts) */
.orbsay { position: absolute; left: 0; right: 0; bottom: 0; margin: 0; text-align: center; pointer-events: none; z-index: 2; }
.orbsay[hidden] { display: none; }
/* the ribbon's failed line, when RETRY can send his words again: the part is the button, 44 pt tall (features/core/ribbon.ts) */
html .ribbon .ribretry { display: inline-flex; align-items: center; min-height: var(--g-target); cursor: pointer; }
/* end hero: mind */

/* =====================================================================
   route C part 2 — every other screen (docs/build-plan/BRIEF-DESIGN-BUILD-2.md; the mock-ups in
   docs/build-plan/mockups/c). The same language as part 1's layer above: a graphite canvas, glass cards with a
   1 px white-8 % hairline, one type scale, the reactor's colour only for what is live, amber only for warnings,
   neutral glass for icons and controls, 44 pt targets. Its rules start with html, like part 1's.
   Everything up to "end route C part 2" is this layer.
   ===================================================================== */
#rcoffline { display: none; }
.gymlvnone, .wnall { display: none; }

/* ---------- a screen's head: the large title in the bar, then the state as a title and one line ---------- */
html .two > .hero { align-items: flex-start; text-align: left; gap: 0; padding: 0 2px 2px; }
html .two .bigv { font: 700 22px/28px var(--sfd); letter-spacing: -.3px; color: var(--ink); }
html .two .bigv:empty { display: none; }
html .two .sub { margin-top: 3px; font: 400 15px/20px var(--sf); letter-spacing: -.12px; color: var(--ink2); }
html .two .sub:empty { display: none; }
html .listmode .two > .hero { align-items: flex-start; text-align: left; padding: 0 4px 6px; }
html .listmode .two .bigv { font-size: 22px; }

/* ---------- the segmented control (a page's two sides): one glass track, the chosen side lit ---------- */
html .two:not(.stack) .swap { height: 44px; min-height: 44px !important; margin: 14px 0 2px; padding: 4px; gap: 0; border-radius: 14px; background: rgba(255,255,255,.055) !important; box-shadow: inset 0 0 0 1px var(--hair) !important; }
html .two .swap::before, html .two .swap::after { height: 36px; border-radius: 10px !important; font: 600 14px/1 var(--sf); letter-spacing: -.1px; color: var(--ink2); background: transparent !important; box-shadow: none !important; transition: background var(--rcsp) var(--spring), color .2s, box-shadow var(--rcsp) var(--spring); }
html .two:not(.alt) .swap::before, html .two.alt .swap::after { color: var(--ink); background: rgba(255,255,255,.13) !important; box-shadow: inset 0 0 0 1px rgba(255,255,255,.07), 0 2px 8px rgba(0,0,0,.35) !important; }

/* ---------- glass cards: the panel's head (title 17, its state at the right) ---------- */
html .pn > h3 small, html .pn > h3 small[data-label] { --lfs: 13px; font: 400 13px/18px var(--sf); color: var(--ink3); white-space: nowrap; }
html .pn > h3 .ptitle[data-label] { --lfs: 17px; }
html .pn .note { font: 400 15px/20px var(--sf); letter-spacing: -.12px; color: var(--ink2); }
html .pn .rw { border-bottom-color: var(--hair); }
html .pn .rw .k { color: var(--ink2); }
html .pn .rw .v { color: var(--ink); }
html .pn .rw .n { color: var(--ink3); font-variant-numeric: tabular-nums; }

/* ---------- fields: route C inputs — glass, a hairline, the accent ring when typing ---------- */
html :is(.pn, .modal) :is(input:not([type=checkbox], [type=radio], [type=range], [type=file], [type=color]), select, textarea) { min-height: 44px; border-radius: 14px; background-color: rgba(255,255,255,.06); box-shadow: inset 0 0 0 1px var(--hair); font: 400 17px/22px var(--sf); letter-spacing: -.25px; color: var(--ink); }
html :is(.pn, .modal) :is(input, select, textarea)::placeholder { color: var(--ink3); }
html :is(.pn, .modal) :is(input:not([type=checkbox], [type=radio], [type=range], [type=file], [type=color]), select, textarea):focus { background-color: rgba(255,255,255,.085); box-shadow: inset 0 0 0 1px rgba(var(--cr), .55), 0 0 0 4px rgba(var(--cr), .13) !important; }
html :is(.pn, .modal) select { background-image: linear-gradient(45deg, transparent 50%, var(--ink3) 50%), linear-gradient(135deg, var(--ink3) 50%, transparent 50%); }

/* ---------- an empty list: what it is, and one sentence on what to do next ---------- */
html .empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; min-height: 104px; padding: 20px 16px; text-align: center; }
html .empty b { --lfs: 17px; display: block; font: 600 17px/22px var(--sf); letter-spacing: -.25px; color: var(--ink); }
html .empty b[data-label]::before { font-weight: 600; line-height: 22px; }
html .empty span { --lfs: 15px; display: block; max-width: 300px; font: 400 15px/20px var(--sf); color: var(--ink3); }
html .empty span[data-label]::before { line-height: 20px; }
html .empty.bad b { color: var(--amber); }
html .empty.wait b::after { content: ''; display: block; width: 44px; height: 3px; margin: 10px auto 0; border-radius: 2px; background: linear-gradient(90deg, transparent, rgba(var(--cr), .85), transparent); animation: rcload 1.2s ease-in-out infinite; }
@keyframes rcload { 0%, 100% { opacity: .25; transform: scaleX(.6); } 50% { opacity: 1; transform: scaleX(1); } }

/* ---------- offline: one quiet amber line above the tab bar (Home has its own pill) ---------- */
html body.offline:not([data-tab="core"]) #rcoffline { display: block; text-align: center; position: fixed; z-index: 40; left: 50%; bottom: calc(64px + 24px + max(12px, calc(env(safe-area-inset-bottom, 0px) - 6px))); transform: translateX(-50%); max-width: calc(100% - 32px); width: max-content; min-height: 36px; padding: 8px 14px; border-radius: 18px; font: 400 13px/18px var(--sf); color: var(--ink2); background: rgba(30,27,22,.82); box-shadow: inset 0 0 0 1px rgba(var(--amberr), .28), 0 12px 30px rgba(0,0,0,.45); -webkit-backdrop-filter: blur(24px) saturate(1.6); backdrop-filter: blur(24px) saturate(1.6); pointer-events: none; animation: rcrise var(--rcsp) var(--spring) both; }
html body.offline.ownback #rcoffline { bottom: calc(76px + max(14px, calc(env(safe-area-inset-bottom, 0px) - 4px))); }
html #rcoffline i { display: inline-block; margin-right: 8px; vertical-align: 1px; width: 7px; height: 7px; flex: none; border-radius: 4px; background: var(--amber); box-shadow: 0 0 8px var(--amber); }
html #rcoffline b { flex: none; font-weight: 600; color: var(--amber); }
html #rcoffline span { min-width: 0; }
@keyframes rcrise { from { opacity: 0; transform: translate(-50%, 8px); } }

/* ---------- polish of part 1 ---------- */
/* GYM: the line under the title (the mock-up's), and LEVELS BY GAME before anything is trained */
html #pg-gym .two > .hero .sub { display: block; }
html #pg-gym .gymlvls.none .b { background: rgba(235,240,245,.07); box-shadow: none; }
html #pg-gym .gymlvls.none .g { display: none; }
html #pg-gym .gymlvls .gymlvnone { display: block; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); max-width: calc(100% - 8px); padding: 6px 12px; border-radius: 14px; font: 400 13px/18px var(--sf); color: var(--ink2); text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; background: rgba(10,12,14,.72); box-shadow: inset 0 0 0 1px var(--hair); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
html #pg-gym .gymlvls .gymlvnone b { font-weight: 600; color: var(--ink); }
/* WHAT'S NEW: a card — the newest three, Show all for the rest, GOT IT as a small pill in its corner */
