html #pg-settings .two > .hero .bigv::before { color: var(--ink); background: radial-gradient(circle at 35% 30%, #3d454d, #15191c 75%); box-shadow: inset 0 0 0 1px var(--hair2), inset 0 1px 0 rgba(255,255,255,.12), 0 0 0 4px rgba(var(--cr), .06); }
html #pg-settings .two > .hero .bigv { font: 700 22px/28px var(--sfd); letter-spacing: -.3px; }
/* Home: the ask bar's chat button as a neutral glass button */
