html .pn .bar, html .modal .bar { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto 4px; column-gap: 12px; row-gap: 7px; align-items: center; min-height: 0; font: 500 15px/20px var(--sf); letter-spacing: -.12px; color: var(--ink); text-transform: none; }
