/* a button that is a switch (role=switch, aria-checked): its words, then an iOS knob */
html button[role="switch"].rcswitch { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; height: 52px; min-height: 52px !important; padding: 0 70px 0 16px; border-radius: 16px; color: var(--ink) !important; background: rgba(255,255,255,.055) !important; box-shadow: inset 0 0 0 1px var(--hair) !important; text-align: left; }
