html #pg-library .libtile { grid-area: t; display: grid; place-items: center; width: 36px; height: 36px; border-radius: 10px; background: rgba(255,255,255,.08); box-shadow: inset 0 0 0 1px var(--hair); color: var(--ink); }
html #pg-library .libtile .ic { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
