html #pg-library :is(.pn.shelf, .pn.gadgets) .rw .k { grid-area: k; align-self: start; min-width: 0; font: 400 13px/17px var(--sf); letter-spacing: -.04px; color: var(--ink3); text-transform: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
