html .pn.tl .mih :is(.k, .mik) { --lfs: 11px; min-width: 0; font: 600 11px/13px var(--sf); letter-spacing: .06em; text-transform: uppercase; color: var(--ink3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html .pn.tl .mih .k { flex: none; }
