html .pn.tl .milock { display: inline-flex; align-items: center; gap: 4px; flex: none; margin-left: auto; height: 20px; padding: 0 8px; border-radius: 10px; font: 700 10.5px/1 var(--sf); letter-spacing: .08em; color: var(--c); background: rgba(var(--cr), .13); }
