/* ---------- one icon language: bare thin glyphs in the secondary ink, never a tile behind them ("like app
   icons", OWNER-ISSUES 32); 22 pt in rows and cards; the accent only for the live or selected one ---------- */
:is(.sq, .rowic, .gic, .rctile) { display: grid; place-items: center; flex: none; background: none !important; box-shadow: none !important; border: 0 !important; border-radius: 0 !important; }
:is(.sq, .rowic, .gic, .rctile) .ic { width: 22px !important; height: 22px !important; padding: 0 !important; fill: none; stroke: var(--l2, var(--mute)) !important; stroke-width: 1.7 !important; stroke-linecap: round; stroke-linejoin: round; background: none !important; box-shadow: none !important; }
:is(.rowic, .gic, .rctile, .merow .sq, .addrow .sq) { width: 28px !important; height: 28px !important; }
:is(.hubtile, .hubhero) .sq { width: 28px !important; height: 28px !important; justify-items: start; }
.recent .sq { width: 40px !important; height: 40px !important; }
.recent .sq .ic { width: 28px !important; height: 28px !important; stroke-width: 1.6 !important; }
:root #pg-gym .gymcard .sq.gymglyph { width: 28px; height: 28px; background: none !important; box-shadow: none !important; }
:root #pg-gym .gymcard .sq.gymglyph .ic { stroke: var(--l2, var(--mute)) !important; }
:root #pg-memory .addrow .sq.sq { background: none !important; }
:root #app .listmode .pn[data-row] > h3 > .rowic.rowic { width: 28px; height: 28px; background: none !important; box-shadow: none !important; border-radius: 0; }
:root #app .listmode .pn[data-row] > h3 > .rowic.rowic .ic { stroke: var(--l2, var(--mute)) !important; }
:root #pg-memory .addrow .sq.sq .ic, :root #palette .it.sel .gic .ic { stroke: var(--acc, var(--c)) !important; }
/* ---------- Every screen (shell/launcher.ts): H's tap-to-find-out cards, F's miniatures, G's YOU CAN rows and picks,
   the "Go to, or ask…" pill. Calm glass, one accent light (the reactor's colour) for "you are here", what is due and
   OPEN. Its own tokens, so it reads the same in every look. ---------- */
:root #deck {
  --dk1: var(--ink, #f4f6f8); --dk2: var(--ink2, rgba(235,240,245,.64)); --dk3: var(--ink3, rgba(235,240,245,.4)); --dk4: var(--ink4, rgba(235,240,245,.2));
  --dkhair: var(--hair, rgba(255,255,255,.08)); --dkhair2: var(--hair2, rgba(255,255,255,.13)); --dkacc: var(--acc, var(--c));
  --dkf: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Inter', system-ui, 'Helvetica Neue', sans-serif;
  --dkfd: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Inter', system-ui, 'Helvetica Neue', sans-serif;
  --dkspring: cubic-bezier(.32,.72,0,1);
  display: none; padding: 0; align-items: stretch; justify-content: center; color: var(--dk1); font-family: var(--dkf);
  background: #050607; -webkit-backdrop-filter: none; backdrop-filter: none;
}
:root #deck.on { display: block; animation: dkfade .3s ease-out both; }
@keyframes dkfade { from { opacity: 0; } }
#deck::before { content: ''; position: absolute; left: -200px; top: -170px; width: 760px; height: 600px; pointer-events: none; background: radial-gradient(closest-side, color-mix(in srgb, var(--dkacc) 10%, transparent), color-mix(in srgb, var(--dkacc) 3.5%, transparent) 50%, transparent); }
#deck::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: calc(120px + env(safe-area-inset-bottom, 0px)); pointer-events: none; background: linear-gradient(180deg, rgba(5,6,7,0), rgba(5,6,7,.86) 62%, rgba(5,6,7,.97)); }
#deck :is(button, button *, input) { text-transform: none; letter-spacing: normal; font-family: var(--dkf); }
#deck button { -webkit-tap-highlight-color: transparent; }
#deck .dk { position: absolute; inset: 0; z-index: 1; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; outline: 0; scroll-padding: 12px 0 calc(env(safe-area-inset-bottom, 0px) + 84px);
  padding: calc(env(safe-area-inset-top, 0px) + 18px) max(16px, calc((100% - 600px) / 2)) calc(env(safe-area-inset-bottom, 0px) + 112px); }
#deck .dk::-webkit-scrollbar { display: none; }
#deck .dkk { display: block; font: 600 11px/13px var(--dkf); letter-spacing: .09em; text-transform: uppercase; color: var(--dk3); }
/* header: EVERY SCREEN, "At your service, {name}", one line */
