#deck .dkclose { flex: none; display: grid; place-items: center; width: 44px; height: 44px; min-height: 44px; padding: 0; margin-top: -2px; border-radius: 22px; border: 0; background: rgba(255,255,255,.075); box-shadow: inset 0 0 0 1px var(--dkhair); color: var(--dk1); }
#deck .dkclose .ic, #deck .dkless .ic, #deck .dkmic .ic, #deck .dksearch { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
/* TRY THIS NOW: three small glass cards, sideways */
#deck .dktry { margin-top: 24px; }
