#deck .dktrys { display: flex; gap: 10px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; margin: 0 -16px; padding: 0 16px 2px; scroll-padding: 0 16px; }
#deck .dktrys::-webkit-scrollbar { display: none; }
#deck .dkpick { flex: none; scroll-snap-align: start; display: flex; flex-direction: column; align-items: flex-start; gap: 0; width: 236px; min-height: 44px; padding: 12px 14px 12px; border-radius: 20px; text-align: left; white-space: normal; color: var(--dk1);
  background: linear-gradient(160deg, color-mix(in srgb, var(--dkacc) 7%, transparent), rgba(255,255,255,.03) 60%); border: 1px solid rgba(255,255,255,.1); box-shadow: inset 0 1px 0 rgba(255,255,255,.055), 0 18px 40px rgba(0,0,0,.42); }
