/* THE FREE LEVELS' cards: the pack's author under its title; what it plays over; the DeHackEd line where it ships one */
html .arcby { margin: -2px 0 4px; font: 500 13px/18px var(--sf); color: var(--c2); }
html .arcover, html .arcdeh { margin: 0 0 6px; font: 400 13px/18px var(--sf); color: var(--ink3); }
@media (orientation: landscape) {
  html .arcscreen.doom { top: 0; height: 100dvh; width: auto; max-height: none; max-width: 100vw; }
  html .arcscreen.quake { top: 0; left: 0; transform: none; width: 100%; height: 100%; aspect-ratio: auto; max-height: none; max-width: none; }
}
