@media (min-width: 1000px) { .tvflat { margin-left: 104px; } }
.tvflat .tvmap { position: relative; display: flex; flex-direction: column; gap: 5px; height: calc(100dvh - 200px); min-height: 320px; border-radius: 18px; overflow: hidden; }
