/* TV MODE (body.tv): targets of 56 pt at least, a focus ring you can see from the sofa, the deck as big tiles, the chat bigger */
html body.tv :is(#app, #deck, #tvkb, .modal, #mesheet) :where(button, [role="button"], [role="switch"], [role="tab"], a[href], select, input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), textarea) { min-height: 56px !important; }
html body.tv :is(#app, #deck, #tvkb, .modal, #mesheet) :where(button, [role="button"], [role="switch"], [role="tab"]) { min-width: 56px !important; }
body.tv :focus-visible { outline: 4px solid rgb(var(--accr)) !important; outline-offset: 3px; box-shadow: 0 0 0 9px rgba(var(--accr), .22) !important; }
body.tv .tvline { font-size: 21px; line-height: 29px; }
body.tv #deck .dk { padding-left: 64px !important; padding-right: 64px !important; }
