.trusttable { list-style: none; margin: 0; padding: 0; min-width: 0; }
.trustrow { display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto; gap: 2px 8px; align-items: baseline; padding: 8px 0; border-top: 1px solid rgba(127, 127, 127, .2); min-width: 0; }
