.indspans, .indsheet .indbrain, .indsheet .indtruth, .indsheet .indceiling { min-width: 0; overflow-wrap: anywhere; }
.indcat { display: flex; flex-direction: column; gap: 2px; padding: 8px 0; border-top: 1px solid rgba(127, 127, 127, .2); min-width: 0; }
.indcat b { font: 600 14px/1.3 var(--sf); }
.indcat .indnums { font: 500 13px var(--mono, monospace); opacity: .85; overflow-wrap: anywhere; }
