.indsheet .indtruth { margin-top: 10px; }
.indsheet .indceiling { margin-top: 6px; opacity: .8; }
.brindep { margin: 6px 0 0; font: 500 14px/1.35 var(--sf); opacity: .9; overflow-wrap: anywhere; }
