.trustwhich div { overflow-wrap: anywhere; }
/* ---- [restd] DESIGN A BUILD (BRIEF-REST-D 1): the Studio's eighth pane and its stage, and the sheet ---- */
.studioseg { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.studioseg button { grid-column: span 2; }
