html .studioseg button { white-space: normal; overflow: visible; text-overflow: clip; overflow-wrap: anywhere; height: auto; min-height: 44px !important; line-height: 1.15; }
.buildstage { position: absolute; inset: 0; z-index: 3; overflow: hidden; border-radius: inherit; background: #cfe3f2; touch-action: none; user-select: none; -webkit-user-select: none; }
