.buildhud { position: absolute; left: 8px; right: 8px; top: 8px; z-index: 4; display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; pointer-events: none; }
.buildname { min-width: 0; overflow: hidden; padding: 5px 10px; border-radius: 999px; background: rgba(8,10,14,.62); color: #fff; font: 600 13px/1.25 var(--sf); white-space: nowrap; text-overflow: ellipsis; }
.buildhud .buildchips { display: flex; flex: none; gap: 6px; pointer-events: auto; }
.buildstage .buildchips button { min-height: 40px; padding: 0 12px; border-radius: 999px; background: rgba(8,10,14,.62); color: #fff; font: 600 12px/1 var(--sf); }
.buildnote { position: absolute; left: 8px; right: 8px; bottom: 8px; z-index: 4; padding: 4px 9px; border-radius: 10px; background: rgba(8,10,14,.55); color: rgba(255,255,255,.9); font: 400 10.5px/1.35 var(--sf); pointer-events: none; }
.buildnote:empty { display: none; }
.buildtag { position: absolute; left: 0; top: 0; z-index: 5; max-width: 70%; overflow: hidden; padding: 5px 10px; border-radius: 999px; background: rgba(8,10,14,.85); color: #fff; font: 600 13px/1.2 var(--sf); white-space: nowrap; text-overflow: ellipsis; pointer-events: none; }
