.buildwordsnote:empty { display: none; }
.build .buildtitle, .buildpane .buildtitle { margin: 0; font: 600 17px/1.3 var(--sf); color: var(--ink); }
.buildsum { margin: 2px 0; font: 400 13px/1.4 var(--sf); color: var(--ink2); }
.buildest { margin: 2px 0; font: 600 14px/1.35 var(--sf); color: var(--ink); }
