.buildfield { display: flex; align-items: center; gap: 6px; min-width: 0; padding: 2px 8px; border-radius: 12px; background: rgba(255,255,255,.05); box-shadow: inset 0 0 0 1px var(--hair); }
.buildfield span { flex: none; font: 500 12px/1.2 var(--sf); color: var(--ink2); }
