.buildfield small { flex: none; color: var(--ink2); }
.buildtick { display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 8px; color: var(--ink); font: 500 14px var(--sf); }
.buildtick input { width: 22px; height: 22px; }
.buildlist { display: flex; flex-direction: column; gap: 6px; }
