html .scanstage .scansky { position: absolute; inset: 0; display: block; pointer-events: none; background: linear-gradient(180deg, rgba(var(--g-accent-pale-rgb), .13) 0%, rgba(var(--g-accent-pale-rgb), .07) 22%, rgba(var(--g-bone-rgb), .04) 34%, transparent 46%), radial-gradient(ellipse 70% 20% at 50% 36%, rgba(var(--g-bone-rgb), .06), transparent 70%); }
html .scanstage[data-hour="day"] .scansky, html .scanstage[data-place="out"] .scansky { background: linear-gradient(180deg, rgba(var(--g-accent-pale-rgb), .22) 0%, rgba(var(--g-accent-pale-rgb), .1) 32%, transparent 60%); }
html .scanstage[data-place="way"] .scansky { background: linear-gradient(180deg, rgba(var(--g-accent-pale-rgb), .16) 0%, rgba(var(--g-accent-pale-rgb), .07) 30%, transparent 55%), radial-gradient(ellipse 70% 30% at 85% 28%, rgba(var(--g-amber-rgb), .09), transparent 70%); }
html .scanstage .scanlamp { position: absolute; inset: 0; display: block; pointer-events: none; background: radial-gradient(ellipse 30% 22% at 62% 58%, rgba(var(--g-amber-rgb), calc(.12 * var(--g-glow))), transparent 70%); opacity: 0; }
