html #app button.scanret { position: absolute; z-index: 2; box-sizing: border-box; min-width: var(--g-target); min-height: var(--g-target) !important; height: auto !important; margin: 0; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; color: inherit; font: inherit; text-transform: none; letter-spacing: normal; white-space: nowrap; cursor: pointer; transform: none; transition: none; }
