  html .orbframe { position: absolute; left: 0; right: 0; top: 0; bottom: 0; z-index: 1; box-sizing: border-box; overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; padding: calc(max(env(safe-area-inset-top, 0px), 14px) + var(--g-s-1)) var(--g-gutter) max(var(--g-s-2), env(safe-area-inset-bottom, 0px)); background: var(--g-canvas); color: var(--g-ink-1); }
