html #thestage { position: fixed; z-index: 30; left: var(--g-gutter); right: var(--g-gutter); bottom: var(--stage-bottom, 96px); width: auto; max-width: 408px; margin: 0 auto; height: var(--stage-h, 420px); display: flex; flex-direction: column; gap: var(--g-s-1); padding: var(--g-s-2); box-sizing: border-box; overflow: hidden; animation: stgin var(--g-dur-bring) var(--g-ease-bring) both; }
