@keyframes stgin { from { opacity: 0; transform: translateY(var(--g-s-3)); } to { opacity: 1; transform: none; } }
@keyframes stgout { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateY(var(--g-s-2)); } }
