.wspanel, .wsask, .wsresults { display: flex; flex-direction: column; gap: var(--g-s-1); min-width: 0; padding: var(--g-s-1); background: var(--g-plate-fill); border: var(--g-hair) solid var(--g-line-faint); border-radius: var(--g-radius-cell); }
