.wsprop { display: grid; grid-template-columns: minmax(0, 36%) minmax(0, 1fr); gap: var(--g-s-1); align-items: center; }
.wspn { display: flex; flex-direction: column; font: var(--g-t-caption); color: var(--g-ink-1); overflow-wrap: anywhere; }
