.wscardmv { flex: none; padding: 0; width: var(--g-target); }
.wscoladd { align-self: flex-start; }
.wsghost { position: fixed; left: 0; top: 0; z-index: 9999; pointer-events: none; box-shadow: 0 0 0 var(--g-stroke) var(--g-accent); background: var(--g-plate-strong-fill); border-radius: var(--g-radius-cell); opacity: .95; }
.wscalhead { justify-content: space-between; flex-wrap: nowrap; }
.wsmonthname { flex: 1 1 auto; text-align: center; font: var(--g-t-head); }
.wscal { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 2px; touch-action: pan-y; }
.wsdow { text-align: center; font: var(--g-t-tag); letter-spacing: var(--g-tr-tag); color: var(--g-ink-3); }
.wsday { display: flex; flex-direction: column; align-items: stretch; gap: 1px; padding: 2px; min-height: 56px; min-width: 0; overflow: hidden; text-align: start; text-transform: none; letter-spacing: 0; background: var(--g-plate-fill); border: var(--g-hair) solid var(--g-line-faint); border-radius: var(--g-radius-cell); }
.wsday[data-in=""] { opacity: .5; }
