.wsdot { display: block; font: var(--g-t-fine); line-height: 1.2; background: color-mix(in srgb, var(--g-accent) 28%, transparent); border-radius: 2px; padding: 0 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wsday small { font: var(--g-t-fine); color: var(--g-ink-3); }
.wstlscroll { position: relative; touch-action: pan-x pan-y; }
