.wsticks { position: absolute; left: 0; top: 0; height: 24px; width: 100%; border-bottom: var(--g-hair) solid var(--g-line-faint); }
.wstick { position: absolute; top: 4px; font: var(--g-t-fine); color: var(--g-ink-3); white-space: nowrap; }
.wstlrow { position: relative; height: var(--g-target); }
.wsbarbtn { position: absolute; top: 0; height: var(--g-target); min-height: var(--g-target); padding: 0; text-align: start; text-transform: none; letter-spacing: 0; background: color-mix(in srgb, var(--g-accent) 30%, transparent); border: var(--g-hair) solid var(--g-accent); border-radius: var(--g-radius-cell); }
.wsgallery { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: var(--g-s-1); }
.wsgcard { display: flex; flex-direction: column; align-items: stretch; gap: 2px; padding: 0 0 var(--g-s-1); text-align: start; text-transform: none; letter-spacing: 0; background: var(--g-plate-fill); border: var(--g-hair) solid var(--g-line-faint); border-radius: var(--g-radius-cell); overflow: hidden; }
.wsgcard b { padding: 0 var(--g-s-1); overflow-wrap: anywhere; font: var(--g-t-body); font-weight: 700; }
