.wsgpic i { font: 700 28px/1 var(--g-font-text); font-style: normal; color: var(--g-ink-3); }
.wsproprow { display: flex; flex-direction: column; gap: var(--g-s-half); padding-block: var(--g-s-half); border-bottom: var(--g-hair) solid var(--g-line-faint); }
.wsproprow input { flex: 1 1 120px; }
.wskind { padding: var(--g-s-1) var(--g-s-2); }
