.wsver { display: flex; flex-direction: column; gap: 2px; padding: var(--g-s-1) var(--g-s-2); align-items: flex-start; }
.wsver[aria-pressed="true"] { box-shadow: inset 0 0 0 var(--g-stroke) var(--g-accent); }
.wsvers { display: flex; flex-direction: column; gap: var(--g-s-half); }
.wsver small { font: var(--g-t-caption); color: var(--g-ink-3); text-transform: none; letter-spacing: 0; }
.wsvpreview { display: flex; flex-direction: column; gap: var(--g-s-half); }
